/* 2026-11-14: the VA series was added at the end (12 guides, keys v1 to v12, audience "va"): one a month to GoHighLevel
   contacts tagged "va lead". The same words as mo-care.com/email-assets/library.json. */
const CC_EMAIL_LIBRARY = [{"id":1,"photo":"scene-kitchen-coffee","month":"January","when":"Early January","cat":"Promo","ac":"#4f8f74","subj":"A gentler kind of New Year's resolution","pre":"This year, you don't have to do it all alone.","eye":"New Year · A Fresh Start","head":"What if this year, you asked for a little help?","hero":"senior and caregiver laughing over morning coffee","blocks":[{"t":"p","text":"Every January brings a flurry of resolutions, eat better, move more, worry less. But if you've been quietly carrying the weight of caring for an aging parent or spouse, here's one worth adding to the list: let someone help."},{"t":"p","text":"At Caring Companions, “help” doesn't mean handing over control. It means a trusted caregiver who folds the laundry, drives to appointments, and shares a cup of coffee, so you can go back to being a daughter, a son, or a spouse instead of the on-call everything."},{"t":"tip","text":"No long-term contract. No rigid packages. Just the hours and support that fit your family, adjusted any time life changes."},{"t":"p","text":"We've walked alongside more than 400 Southwest Missouri families since 2017. We'd be honored to walk alongside yours."},{"t":"p","text":"A few hours of help a week can cover:"},{"t":"l","items":["Laundry and light housekeeping","Meals, with extra for later","Errands and rides to appointments","Medication reminders","Good company"]},{"t":"links","head":"More that may help","items":[{"t":"What happens at the free assessment","d":"60 to 90 minutes at home, no decision needed that day","href":"https://mo-care.com/before-your-assessment"},{"t":"Care cost calculator","d":"See what a week of care might cost","href":"https://mo-care.com/cost-calculator"},{"t":"Caregiver burnout","d":"The signs, and what to do about them","href":"https://mo-care.com/guides/caregiver-burnout"}]}],"cta":{"label":"Schedule a Free Consultation","href":"https://mo-care.com/schedule-consultation","kind":"link"},"sign":"Warmly,","aud":"monthly","key":"m1","banner":"h1","seg":"Promo","footer":""},{"id":2,"photo":"scene-mom-waiting","month":"January","when":"Late January","cat":"Educational","ac":"#5d7896","subj":"The quiet danger of a long Missouri winter","pre":"Loneliness can be as hard on health as a chronic illness.","eye":"Caregiving Insights","head":"When the days get short, watch for the quiet signs","hero":"older adult by a frosted winter window, warm interior","blocks":[{"t":"p","text":"Winter in Southwest Missouri can keep anyone indoors, but for an older adult living alone, weeks of gray skies and icy sidewalks can slide quietly into isolation. And loneliness isn't just sad; research links it to higher risks of depression, cognitive decline, and heart trouble."},{"t":"p","text":"A few things to gently look for in the parent or grandparent you love:"},{"t":"l","items":["Less interest in hobbies, phone calls, or the church they used to enjoy","Skipped meals, or a fridge that stays full","Wearing the same clothes, or letting tidy routines slip","A flatter, quieter mood than usual"]},{"t":"p","text":"Sometimes the fix is simply a familiar face a few times a week, someone to share a meal, a walk, or a memory. That's the heart of what our caregivers do."},{"t":"tip","text":"Can't visit as often as you'd like? A caregiver visit a few times a week can fill the quiet days."},{"t":"p","text":"Small things that help through a long winter:"},{"t":"l","items":["A call at the same time every day, so there is something to count on","A ride to church, a friend's house or lunch out once a week","A visit from a caregiver for company and a hot meal"]},{"t":"links","head":"More that may help","items":[{"t":"Companion care","d":"Company, meals and a hand around the house","href":"https://mo-care.com/services/companion-care"},{"t":"Eating well as we age","d":"What to watch for when meals start slipping","href":"https://mo-care.com/guides/eating-well-as-we-age"},{"t":"Early Support Visits","d":"Help and good company, once a month or every other week","href":"https://mo-care.com/early-support-visits"}]}],"cta":{"label":"Learn About Companionship Care","href":"https://mo-care.com/companionship-care","kind":"link"},"sign":"With care,","aud":"monthly","key":"m2","banner":"h2","seg":"Educational","footer":""},{"id":3,"photo":"hero-caregiver-sofa","month":"February","when":"Feb 7–13","cat":"Holiday","ac":"#b9694a","subj":"Love is showing up, even when you can't","pre":"A little companionship goes a long way this February.","eye":"Valentine's Day","head":"The most loving thing isn't always something you can do yourself","hero":"caregiver and senior playing cards together, laughing","blocks":[{"t":"p","text":"This Valentine's season, love might look less like flowers and more like making sure Mom isn't spending another afternoon alone. If you live across town, or across the country, that can be a hard truth to sit with."},{"t":"p","text":"Companionship care exists for exactly this: a caregiver who genuinely enjoys your loved one's stories, plays the card games they love, and notices when something's off, so the people you love feel seen, even on the days you can't be there."},{"t":"q","text":"Wonderful care. They made my dad very comfortable and dealt with him using compassion and friendship.","by":", Debbie B., Google review"},{"t":"p","text":"Because at Caring Companions, our caregivers don't just provide a service. They extend the warmth of family."},{"t":"links","head":"More that may help","items":[{"t":"Companion care","d":"Company, meals and a hand around the house","href":"https://mo-care.com/services/companion-care"},{"t":"Early Support Visits","d":"Help and good company, once a month or every other week","href":"https://mo-care.com/early-support-visits"},{"t":"Our caregivers","d":"Who comes to your door","href":"https://mo-care.com/our-caregivers"}]}],"cta":{"label":"Call (417) 234-8494","href":"tel:4172348494","kind":"call"},"sign":"Happy Valentine's Day,","aud":"monthly","key":"m3","banner":"h3","seg":"Holiday","footer":""},{"id":4,"photo":"scene-kitchen-walker","month":"February","when":"Late February","cat":"Awareness","ac":"#b9694a","subj":"A few small things that protect an aging heart","pre":"February is American Heart Month, here's what helps at home.","eye":"American Heart Month","head":"Heart-healthy living gets harder alone, and easier with a hand","hero":"a healthy home-cooked meal being shared at the table","blocks":[{"t":"p","text":"Eating well, staying active, taking medications on time, the basics of heart health sound simple, until age, mobility, or memory get in the way. American Heart Month is a good moment to check in on the daily habits that keep an older heart strong."},{"t":"l","items":["Home-cooked, lower-sodium meals instead of whatever's easiest","A daily walk, even just around the living room","Medications taken correctly, and on schedule","Fewer stressful errands and more restful days"]},{"t":"p","text":"These are exactly the everyday things our caregivers help with, quietly, consistently, in the background of a normal day."},{"t":"links","head":"More that may help","items":[{"t":"Living well with heart failure","d":"Daily habits that help","href":"https://mo-care.com/guides/living-well-with-heart-failure"},{"t":"Eating well as we age","d":"What to watch for when meals start slipping","href":"https://mo-care.com/guides/eating-well-as-we-age"},{"t":"Medication management","d":"One list, kept right","href":"https://mo-care.com/guides/medication-management"}]}],"cta":{"label":"Explore Our Services","href":"https://mo-care.com/our-services","kind":"link"},"sign":"To your family's health,","aud":"monthly","key":"m4","banner":"h4","seg":"Awareness","footer":""},{"id":5,"photo":"scene-family-door","month":"March","when":"Early March","cat":"Educational","ac":"#5d7896","subj":"Noticed something during your last visit?","pre":"The signs are easy to miss, until you know what to look for.","eye":"Caregiving Insights","head":"Trust that little voice that said, “something’s different”","hero":"adult child visiting an aging parent at home","blocks":[{"t":"p","text":"Often it's a visit that does it, you walk into your parent's home and something feels off. Mail piling up. A dent in the car nobody mentioned. Less food in the fridge than there should be. It's easy to talk yourself out of it. Please don't."},{"t":"p","text":"Common signs it may be time for a little support:"},{"t":"l","items":["Unopened bills, or unusual mistakes with money","New bruises, or unsteadiness on their feet","Forgotten medications or doubled-up doses","Weight loss, or expired food in the pantry","Withdrawing from friends and favorite activities"]},{"t":"p","text":"Noticing early is a gift. It means you can put gentle support in place now, and help your loved one stay safe and independent at home far longer."},{"t":"p","text":"If something worried you, here is a gentle way to start:"},{"t":"ol","items":["Write down what you saw and when, while it is fresh.","Talk with them. Start with what you noticed, not with what should change.","Mention it to their doctor at the next visit, or sooner if it is about safety or medications.","Call us for a free assessment at home. There is no decision to make that day."]},{"t":"links","head":"More that may help","items":[{"t":"Understanding dementia and Alzheimer's","d":"What is happening, and what helps","href":"https://mo-care.com/guides/dementia-and-alzheimers"},{"t":"Fall prevention at home","d":"The changes that prevent the most falls","href":"https://mo-care.com/guides/fall-prevention-at-home"},{"t":"What happens at the free assessment","d":"60 to 90 minutes at home, no decision needed that day","href":"https://mo-care.com/before-your-assessment"}]}],"cta":{"label":"Start With a Free Assessment","href":"https://mo-care.com/explore-care-options","kind":"link"},"sign":"We're here when you're ready,","aud":"monthly","key":"m5","banner":"h5","seg":"Educational","footer":""},{"id":7,"photo":"scene-tired","month":"April","when":"Early April","cat":"Awareness","ac":"#4f8f74","subj":"You can't pour from an empty cup","pre":"April is Stress Awareness Month. This one’s for you.","eye":"For Family Caregivers","head":"When was the last time someone took care of you?","hero":"a tired family caregiver taking a quiet, restful moment","blocks":[{"t":"p","text":"If you're the one keeping everything running, the appointments, the meals, the medications, the worry at 2 a.m., this note is for you, not your loved one."},{"t":"p","text":"Caregiver burnout is real, and it creeps in quietly: shorter patience, trouble sleeping, your own health sliding down the list. You are not failing. You are doing the work of several people, and you deserve relief."},{"t":"p","text":"That's what respite care is for. Whether it's a few hours a week or a weekend away, we'll step in so you can rest, recharge, and come back to your loved one as you, not just the caregiver."},{"t":"tip","text":"Asking for help isn't giving up. It's how you keep going."},{"t":"p","text":"It may be time for a break if:"},{"t":"l","items":["You have not had a few hours to yourself in weeks","You are up at night and running on little sleep","You have put off your own doctor, or stopped seeing friends","You find yourself short-tempered, and feel bad about it afterward"]},{"t":"links","head":"More that may help","items":[{"t":"Caregiver burnout","d":"The signs, and what to do about them","href":"https://mo-care.com/guides/caregiver-burnout"},{"t":"Respite care","d":"A break for the family member doing the caring","href":"https://mo-care.com/services/respite-care"},{"t":"Medicare GUIDE respite","d":"For families living with dementia at home","href":"https://mo-care.com/medicare-guide"}]}],"cta":{"label":"Ask About Respite Care","href":"https://mo-care.com/respite-care","kind":"link"},"sign":"Take care of you,","aud":"monthly","key":"m7","banner":"h7","seg":"Awareness","footer":""},{"id":8,"photo":"scene-planning-talk","month":"April","when":"Late April","cat":"Educational","ac":"#4f8f74","subj":"Spring cleaning that could prevent a fall","pre":"A few small changes around the house make a big difference.","eye":"Home Safety","head":"This spring, clean for safety as much as for shine","hero":"a bright, tidy, safe living room with clear walkways","blocks":[{"t":"p","text":"Falls are the leading cause of injury for older adults, and most happen right at home, often over things we stop noticing after years in the same house. A little spring attention can prevent a lot of heartache."},{"t":"l","items":["Clear walkways of cords, clutter, and loose rugs","Add grab bars in the bathroom and good lighting in hallways","Keep everyday items within easy reach","Tidy garden paths and steps before mowing season"]},{"t":"p","text":"Our caregivers help with light housekeeping and these everyday safety habits, so home stays the safest place to be."},{"t":"links","head":"More that may help","items":[{"t":"Fall prevention at home","d":"The changes that prevent the most falls","href":"https://mo-care.com/guides/fall-prevention-at-home"},{"t":"Home safety, room by room","d":"A walk through the house with fresh eyes","href":"https://mo-care.com/guides/home-safety-room-by-room"},{"t":"Light housekeeping","d":"Keeping the house safe and comfortable","href":"https://mo-care.com/services/light-housekeeping"}]}],"cta":{"label":"Learn About Home Support","href":"https://mo-care.com/services/light-housekeeping","kind":"link"},"sign":"Here's to a safe spring,","aud":"monthly","key":"m8","banner":"h8","seg":"Educational","footer":""},{"id":9,"photo":"scene-phone-together","month":"May","when":"May 4–10","cat":"Holiday","ac":"#b9694a","subj":"For every mom who took care of us first","pre":"This Mother’s Day, give her the gift of being cared for.","eye":"Mother's Day","head":"She spent a lifetime caring for everyone else","hero":"a mother and her adult daughter embracing warmly","blocks":[{"t":"p","text":"This Mother's Day, the flowers will be lovely, but the gift she may need most is the one that lasts past the weekend: knowing she's looked after, every day, by someone who treats her like their own."},{"t":"p","text":"For the mom or grandmother who raised you, a caregiver can mean warm meals, a clean home, rides to see friends, and company that brightens an ordinary Tuesday. Dignity, comfort, and a little joy, that's the gift."},{"t":"q","text":"Excellent coordination and fulfillment of care for Mom. Very happy and satisfied with Caring Companions!","by":", Robert G., Google review"},{"t":"p","text":"Happy Mother's Day from all of us at Caring Companions."},{"t":"links","head":"More that may help","items":[{"t":"Early Support Visits","d":"Help and good company, once a month or every other week","href":"https://mo-care.com/early-support-visits"},{"t":"Companion care","d":"Company, meals and a hand around the house","href":"https://mo-care.com/services/companion-care"},{"t":"Our caregivers","d":"Who comes to your door","href":"https://mo-care.com/our-caregivers"}]}],"cta":{"label":"Schedule a Free Consultation","href":"https://mo-care.com/schedule-consultation","kind":"link"},"sign":"With gratitude,","aud":"monthly","key":"m9","banner":"h9","seg":"Holiday","footer":""},{"id":10,"photo":"scene-garden-walker","month":"May","when":"Late May","cat":"Awareness","ac":"#c79a3a","subj":"Aging at home, on her own terms","pre":"May is Older Americans Month, here’s to independence.","eye":"Older Americans Month","head":"Independence doesn't have to mean doing it all alone","hero":"an active senior gardening contentedly at home","blocks":[{"t":"p","text":"This May, Older Americans Month celebrates a truth the years don't erase: older adults want to live on their own terms, in their own homes, surrounded by their own memories. Nearly everyone we serve says the same thing, “I just want to stay home.”"},{"t":"p","text":"The right support makes that possible. Not by taking over, but by quietly filling the gaps, the heavy chores, the long drives, the tasks that have gotten harder, so the things that matter stay in your loved one's hands."},{"t":"tip","text":"Care that grows with you: from a few visits a week to around-the-clock support, your plan changes as needs change."},{"t":"links","head":"More that may help","items":[{"t":"Early Support Visits","d":"Help and good company, once a month or every other week","href":"https://mo-care.com/early-support-visits"},{"t":"Care cost calculator","d":"See what a week of care might cost","href":"https://mo-care.com/cost-calculator"},{"t":"All our services","d":"From a few hours a week to around the clock","href":"https://mo-care.com/our-services"}]}],"cta":{"label":"Explore Care Options","href":"https://mo-care.com/explore-care-options","kind":"link"},"sign":"Celebrating you,","aud":"monthly","key":"m10","banner":"h10","seg":"Awareness","footer":""},{"id":11,"photo":"scene-album-dad","month":"June","when":"June 8–14","cat":"Holiday","ac":"#5d7896","subj":"The strong ones need a hand too","pre":"This Father’s Day, make sure Dad is truly okay.","eye":"Father's Day","head":"Dad spent his life being the strong one","hero":"a father and adult son watching a ballgame together","blocks":[{"t":"p","text":"Fathers are famously bad at asking for help. He'll tell you he's “fine,” wave off the cane, and insist he doesn't need anyone fussing over him. And maybe that independence is exactly why you worry."},{"t":"p","text":"A good caregiver knows how to help a proud man keep his dignity, a hand that looks like friendship, not fussing. Someone to share a ballgame with, keep the house in order, and quietly make sure he's safe."},{"t":"p","text":"This Father's Day, let him stay the strong, independent man he's always been, with just a little backup."},{"t":"links","head":"More that may help","items":[{"t":"Early Support Visits","d":"Help and good company, once a month or every other week","href":"https://mo-care.com/early-support-visits"},{"t":"Companion care","d":"Company, meals and a hand around the house","href":"https://mo-care.com/services/companion-care"},{"t":"See a sample caregiver profile","d":"Meet them before the first visit","href":"https://mo-care.com/our-caregivers#meet-your-caregiver"}]}],"cta":{"label":"Call (417) 234-8494","href":"tel:4172348494","kind":"call"},"sign":"Happy Father's Day,","aud":"monthly","key":"m11","banner":"h11","seg":"Holiday","footer":""},{"id":12,"photo":"scene-hands","month":"June","when":"Mid–Late June","cat":"Awareness","ac":"#6f6196","subj":"Caring for someone whose memory is changing","pre":"June is Alzheimer’s & Brain Awareness Month.","eye":"Alzheimer's & Brain Awareness Month","head":"Memory care, with patience built in","hero":"a caregiver gently holding hands with a senior","blocks":[{"t":"p","text":"When a parent or spouse begins to forget, names, routines, sometimes you, it can be one of the loneliest experiences a family faces. This Alzheimer's & Brain Awareness Month is a reminder that you don't have to navigate it by yourself."},{"t":"p","text":"When your loved one lives with dementia, we offer their caregiver added training for those needs: gentle redirection, steady routines, and the patience to meet your loved one wherever they are today. We care for the whole person, not the diagnosis."},{"t":"l","items":["Safe, familiar daily routines","Calm support through confusion or agitation","Engaging activities that spark connection","Respite so family caregivers can breathe"]},{"t":"p","text":"Wherever you are on this road, we'll walk it with you."},{"t":"links","head":"More that may help","items":[{"t":"Understanding dementia and Alzheimer's","d":"What is happening, and what helps","href":"https://mo-care.com/guides/dementia-and-alzheimers"},{"t":"The Dementia Journey","d":"A free nine-module course for families, no sign-up","href":"https://mo-care.com/family-academy"},{"t":"Medicare GUIDE respite","d":"For families living with dementia at home","href":"https://mo-care.com/medicare-guide"}]}],"cta":{"label":"Learn About Dementia & Memory Care","href":"https://mo-care.com/care-paths/dementia","kind":"link"},"sign":"With patience and heart,","aud":"monthly","key":"m12","banner":"h12","seg":"Awareness","footer":""},{"id":13,"photo":"scene-garden-visit","month":"July","when":"June 30–July 3","cat":"Holiday","ac":"#5d7896","subj":"Independence is worth protecting, at every age","pre":"Happy 4th from Caring Companions.","eye":"Independence Day","head":"This week, we celebrate independence, including theirs","hero":"a multi-generational family gathered on a summer porch","blocks":[{"t":"p","text":"There's something fitting about July. As the fireworks celebrate our country's independence, it's a good moment to think about the independence of the people who raised us, and how to help them keep it."},{"t":"p","text":"For an older adult, independence isn't about doing everything alone. It's about staying in the home they love, keeping their routines, and making their own choices, with just enough support to make it safe."},{"t":"p","text":"That's the whole reason we do this work. Happy Independence Day, from our family to yours."},{"t":"links","head":"More that may help","items":[{"t":"All our services","d":"From a few hours a week to around the clock","href":"https://mo-care.com/our-services"},{"t":"Early Support Visits","d":"Help and good company, once a month or every other week","href":"https://mo-care.com/early-support-visits"},{"t":"What happens at the free assessment","d":"60 to 90 minutes at home, no decision needed that day","href":"https://mo-care.com/before-your-assessment"}]}],"cta":{"label":"Schedule a Free Consultation","href":"https://mo-care.com/schedule-consultation","kind":"link"},"sign":"Happy 4th of July,","aud":"monthly","key":"m13","banner":"h13","seg":"Holiday","footer":""},{"id":14,"photo":"hero-caregiver","month":"July","when":"Mid July","cat":"Educational","ac":"#c79a3a","subj":"Missouri summers are hard on older bodies","pre":"Heat affects seniors faster, here’s how to help.","eye":"Home Safety","head":"When the heat index climbs, older adults are most at risk","hero":"a senior staying cool indoors with a glass of water","blocks":[{"t":"p","text":"A Southwest Missouri July can be brutal, and aging bodies handle heat far less efficiently than younger ones. Many older adults don't feel thirsty until they're already dehydrated, and some keep the AC off out of habit or worry about the bill."},{"t":"l","items":["Encourage water throughout the day, not just at meals","Keep the home cool, and check that the AC actually works","Plan errands for the cooler morning hours","Watch for dizziness, confusion, or flushed, dry skin"]},{"t":"p","text":"Our caregivers keep an eye on all of it, hydration, comfort, and the warning signs, so a hot day stays just a hot day."},{"t":"links","head":"More that may help","items":[{"t":"Companion care","d":"Company, meals and a hand around the house","href":"https://mo-care.com/services/companion-care"},{"t":"Errands and rides","d":"Appointments and shopping in the cooler hours","href":"https://mo-care.com/services/errands-transportation"},{"t":"Eating well as we age","d":"What to watch for when meals start slipping","href":"https://mo-care.com/guides/eating-well-as-we-age"}]}],"cta":{"label":"Explore Our Services","href":"https://mo-care.com/our-services","kind":"link"},"sign":"Stay cool out there,","aud":"monthly","key":"m14","banner":"h14","seg":"Educational","footer":""},{"id":15,"photo":"scene-welcome-porch","month":"August","when":"Early August","cat":"Service","ac":"#4f8f74","subj":"Going on vacation? We'll stay with Mom.","pre":"Respite care means everyone gets a break.","eye":"Service Spotlight · Respite Care","head":"You deserve a real vacation, not a worried one","hero":"a relaxed family happily heading off on vacation","blocks":[{"t":"p","text":"Summer trips are wonderful, until you're the one who handles Mom's care and there's no one to cover. Too many families either cancel the trip or spend it on the phone, worrying."},{"t":"p","text":"Respite care is the answer. For a weekend or a couple of weeks, a trusted caregiver steps into your routine, same meals, same medications, same comforts, so your loved one is safe and content while you actually rest."},{"t":"tip","text":"Respite isn't just for vacations. Even a few regular hours each week can protect a family caregiver's health and patience."},{"t":"p","text":"Planning time away? A few things make the handoff easy:"},{"t":"l","items":["One list of medications and when each is taken","Doctors' names and numbers, and who to call first","The daily routine: meals, favorite shows, bedtime","A short visit with the caregiver before you leave, so it is a face they know"]},{"t":"links","head":"More that may help","items":[{"t":"Respite care","d":"A break for the family member doing the caring","href":"https://mo-care.com/services/respite-care"},{"t":"Overnight care","d":"Someone there through the night","href":"https://mo-care.com/services/overnight-care"},{"t":"24-hour care","d":"Care around the clock, in shifts","href":"https://mo-care.com/services/24-hour-care"}]}],"cta":{"label":"Ask About Respite Care","href":"https://mo-care.com/respite-care","kind":"link"},"sign":"Go enjoy yourself,","aud":"monthly","key":"m15","banner":"h15","seg":"Service","footer":""},{"id":16,"photo":"scene-sofa-album","month":"August","when":"Late August","cat":"Testimonial","ac":"#c79a3a","subj":"What families tell us after the first few months","pre":"In their own words.","eye":"From Our Families","head":"Sometimes the right help changes everything","hero":"a multi-generational family together and at ease at home","blocks":[{"t":"p","text":"When families first call us, they're usually exhausted, a little guilty, and unsure if they're “ready.” We hear the same thing again and again a few months later: we wish we'd called sooner."},{"t":"q","text":"Have been very impressed with the compassionate care my parents have received in their home. The administration has also been very flexible to work with us and very responsive.","by":", Judy B., Google review"},{"t":"p","text":"Since 2017, more than 400 Southwest Missouri families have trusted us with the people they love most. We'd be honored to earn that trust with yours."},{"t":"links","head":"See it for yourself","items":[{"t":"What happens at the free assessment","d":"60 to 90 minutes at home, no decision needed that day","href":"https://mo-care.com/before-your-assessment"},{"t":"Our caregivers","d":"Who comes to your door","href":"https://mo-care.com/our-caregivers"},{"t":"Our rates","d":"$30, $32 or $34 an hour, published","href":"https://mo-care.com/pricing"}]}],"cta":{"label":"Talk With a Care Coordinator","href":"https://mo-care.com/schedule-consultation","kind":"link"},"sign":"Thank you for trusting us,","aud":"monthly","key":"m16","banner":"h16","seg":"Testimonial","footer":""},{"id":17,"photo":"walking-together","month":"September","when":"Early September","cat":"Awareness","ac":"#4f8f74","subj":"Most falls are preventable. Really.","pre":"September is Healthy Aging Month.","eye":"Healthy Aging Month","head":"A fall can change everything, so let's prevent it","hero":"a senior walking confidently with a caregiver’s support","blocks":[{"t":"p","text":"September's Healthy Aging Month carries one message worth repeating: a single fall can undo years of independence in an instant. The good news is that most falls are preventable with a few steady habits and small changes at home."},{"t":"l","items":["Stay active, gentle movement keeps balance and strength","Review medications that can cause dizziness","Wear supportive, non-slip footwear (no loose slippers!)","Light the path from bed to bathroom for nighttime trips"]},{"t":"p","text":"Our caregivers help with all of it, steady support while walking, safer routines, and a watchful eye that catches hazards before they cause harm."},{"t":"links","head":"More that may help","items":[{"t":"Fall prevention at home","d":"The changes that prevent the most falls","href":"https://mo-care.com/guides/fall-prevention-at-home"},{"t":"Home safety, room by room","d":"A walk through the house with fresh eyes","href":"https://mo-care.com/guides/home-safety-room-by-room"},{"t":"Mobility assistance","d":"A steady hand getting around","href":"https://mo-care.com/services/mobility-assistance"}]}],"cta":{"label":"Learn About Mobility Support","href":"https://mo-care.com/services/mobility-assistance","kind":"link"},"sign":"To healthy, steady days,","aud":"monthly","key":"m17","banner":"h17","seg":"Awareness","footer":""},{"id":18,"photo":"scene-puzzle","month":"September","when":"Late September","cat":"Service","ac":"#5d7896","subj":"The secret to great care? The right match.","pre":"How we pair your loved one with the right caregiver.","eye":"Service Spotlight · Caregiver Matching","head":"Anyone can send a caregiver. We send the right one.","hero":"a caregiver and senior who clearly enjoy each other","blocks":[{"t":"p","text":"The difference between care that works and care that doesn't usually comes down to one thing: the person who walks through the door. A great match feels less like hiring help and more like welcoming a friend."},{"t":"p","text":"That's why we don't just fill a shift. Our five-step matching process considers personality, interests, skills, and lifestyle, so your loved one and their caregiver actually click."},{"t":"l","items":["A thoughtful assessment of needs and preferences","Matching on compatibility, not just availability","A flexible start, with room to adjust","Ongoing check-ins to keep it working"]},{"t":"p","text":"And if it's ever not the right fit? We'll make it right."},{"t":"links","head":"More that may help","items":[{"t":"Our caregivers","d":"Who comes to your door","href":"https://mo-care.com/our-caregivers"},{"t":"How our caregivers are trained","d":"What they learn before the first visit","href":"https://mo-care.com/our-caregivers-training"},{"t":"What happens at the free assessment","d":"60 to 90 minutes at home, no decision needed that day","href":"https://mo-care.com/before-your-assessment"}]}],"cta":{"label":"Take Our Care Questionnaire","href":"https://mo-care.com/assessment","kind":"link"},"sign":"Let's find your perfect match,","aud":"monthly","key":"m18","banner":"h18","seg":"Service","footer":""},{"id":19,"photo":"scene-daughter-text","month":"October","when":"Early–Mid October","cat":"Holiday","ac":"#b9694a","subj":"As it cools down, a gentle reminder","pre":"Cozy season is a good time to check in on the ones we love.","eye":"Autumn","head":"The season of slowing down, and looking a little closer","hero":"a cozy autumn scene in a senior’s warm living room","blocks":[{"t":"p","text":"There's a coziness to fall in the Ozarks, sweaters, soups, early evenings. It's also the season when families start gathering again, and when you may notice that the parent you visited last spring seems a little frailer, a little more forgetful, a little more alone."},{"t":"p","text":"If something tugs at you this autumn, trust it. A short conversation now can mean a warm, safe winter for someone you love, and real peace of mind for you."},{"t":"tip","text":"Earlier nights mean more hours alone. A few caregiver visits a week can fill them with warmth and company."},{"t":"links","head":"More that may help","items":[{"t":"Early Support Visits","d":"Help and good company, once a month or every other week","href":"https://mo-care.com/early-support-visits"},{"t":"Understanding dementia and Alzheimer's","d":"What is happening, and what helps","href":"https://mo-care.com/guides/dementia-and-alzheimers"},{"t":"What happens at the free assessment","d":"60 to 90 minutes at home, no decision needed that day","href":"https://mo-care.com/before-your-assessment"}]}],"cta":{"label":"Schedule a Free Consultation","href":"https://mo-care.com/schedule-consultation","kind":"link"},"sign":"Cozy wishes,","aud":"monthly","key":"m19","banner":"h19","seg":"Holiday","footer":""},{"id":20,"photo":"scene-door-wave","month":"October","when":"Late October","cat":"Educational","ac":"#5d7896","subj":"Get the house ready before the first freeze","pre":"A little prep now prevents big problems later.","eye":"Home Safety","head":"Before winter sets in, a few things worth checking","hero":"a warm, well-prepared home interior heading into winter","blocks":[{"t":"p","text":"Winter is hard on an older adult's home, and the tasks that keep it safe, clearing gutters, checking the furnace, salting the steps, get harder to do alone every year. A little preparation now prevents cold, costly, and dangerous surprises later."},{"t":"l","items":["Test the heating system and replace furnace filters","Check smoke and carbon-monoxide detectors","Stock up on essentials before icy weather hits","Have a plan for snow, ice, and slick steps"]},{"t":"p","text":"Our caregivers help keep daily life running through the hardest months, errands, meals, warm company, and a safe path to the door."},{"t":"links","head":"More that may help","items":[{"t":"Home safety, room by room","d":"A walk through the house with fresh eyes","href":"https://mo-care.com/guides/home-safety-room-by-room"},{"t":"Fall prevention at home","d":"The changes that prevent the most falls","href":"https://mo-care.com/guides/fall-prevention-at-home"},{"t":"Errands and rides","d":"Stocking up before the weather turns","href":"https://mo-care.com/services/errands-transportation"}]}],"cta":{"label":"Explore Our Services","href":"https://mo-care.com/our-services","kind":"link"},"sign":"Stay warm,","aud":"monthly","key":"m20","banner":"h20","seg":"Educational","footer":""},{"id":21,"photo":"scene-cafe-outing","month":"November","when":"Nov 10–18","cat":"Awareness","ac":"#b9694a","subj":"This month, we see you","pre":"November is National Family Caregivers Month.","eye":"National Family Caregivers Month","head":"To the family caregivers: thank you, and please rest","hero":"a thanksgiving table surrounded by family","blocks":[{"t":"p","text":"November is National Family Caregivers Month, and Thanksgiving sits right in the middle of it, which feels exactly right. So before the table is set, we want to say it plainly: the quiet, daily work you do for someone you love does not go unseen."},{"t":"p","text":"It's also the season when the work doubles, hosting, traveling, cooking, on top of everything you already carry. Please don't try to do all of it alone. Letting a caregiver cover a few hours isn't stepping back; it's how you make it to the holiday with something left to give."},{"t":"tip","text":"Hosting this year? Respite care can cover the cooking and care so you can simply enjoy your family."},{"t":"p","text":"From our family to yours, thank you, and happy Thanksgiving."},{"t":"links","head":"More that may help","items":[{"t":"Caregiver burnout","d":"The signs, and what to do about them","href":"https://mo-care.com/guides/caregiver-burnout"},{"t":"Respite care","d":"A break for the family member doing the caring","href":"https://mo-care.com/services/respite-care"},{"t":"Medicare GUIDE respite","d":"For families living with dementia at home","href":"https://mo-care.com/medicare-guide"}]}],"cta":{"label":"Ask About Holiday Respite","href":"https://mo-care.com/respite-care","kind":"link"},"sign":"With deep gratitude,","aud":"monthly","key":"m21","banner":"h21","seg":"Awareness","footer":""},{"id":22,"photo":"car-ride","month":"November","when":"Around Nov 11","cat":"Holiday","ac":"#5d7896","subj":"Honoring those who served, at home","pre":"VA-funded home care for the veterans we owe so much.","eye":"Veterans Day","head":"They served our country. Now it's our turn to serve them.","hero":"a veteran and a respectful caregiver in conversation","blocks":[{"t":"p","text":"This Veterans Day, we're thinking of the men and women who gave so much, and of the families now caring for them. What many don't realize is that the care a veteran needs at home may be available at little or no cost through VA programs."},{"t":"p","text":"Caring Companions works with VA Community Care and veteran in-home care programs to bring trained, compassionate caregivers to those who served, with help navigating the benefits along the way."},{"t":"l","items":["VA Community Care and veteran in-home care programs","Help understanding what your loved one qualifies for","Caregivers who honor their service and their dignity"]},{"t":"p","text":"To every veteran in our community: thank you. It would be our privilege to care for you."},{"t":"links","head":"More that may help","items":[{"t":"VA benefits for home care","d":"For veterans and surviving spouses","href":"https://mo-care.com/guides/va-benefits-for-home-care"},{"t":"Care for veterans","d":"How we work with VA Community Care","href":"https://mo-care.com/veterans"},{"t":"What happens at the free assessment","d":"60 to 90 minutes at home, no decision needed that day","href":"https://mo-care.com/before-your-assessment"}]}],"cta":{"label":"Learn About VA-Funded Care","href":"https://mo-care.com/free-care-for-veterans","kind":"link"},"sign":"With respect and gratitude,","aud":"monthly","key":"m22","banner":"h22","seg":"Holiday","footer":""},{"id":23,"photo":"scene-home-hug","month":"December","when":"Dec 15–22","cat":"Holiday","ac":"#4f8f74","subj":"Home for the holidays? Keep your eyes open.","pre":"Holiday visits often reveal what phone calls hide.","eye":"The Holidays","head":"The holidays bring us home, and show us what's really going on","hero":"a family gathered warmly around a Christmas living room","blocks":[{"t":"p","text":"For many families, the holidays are the one time everyone's under the same roof again. And every year, it's during these visits that adult children realize Mom or Dad needs more help than the weekly phone calls let on."},{"t":"p","text":"As you gather this season, notice gently:"},{"t":"l","items":["Is the home as clean and well-stocked as it used to be?","Are they steady on their feet, and keeping up with medications?","Has there been weight loss, or unexplained bruises?","Do they seem more isolated or forgetful than last year?"]},{"t":"p","text":"If you see something that worries you, you don't have to solve it overnight. Start with a conversation, with them, and with us. We'll help you figure out the next gentle step."},{"t":"tip","text":"We care for families right through the holidays. The earlier you call, the better we can plan."},{"t":"p","text":"If something worried you, here is a gentle way to start:"},{"t":"ol","items":["Write down what you saw and when, while it is fresh.","Talk with them. Start with what you noticed, not with what should change.","Mention it to their doctor at the next visit, or sooner if it is about safety or medications.","Call us for a free assessment at home. There is no decision to make that day."]},{"t":"links","head":"More that may help","items":[{"t":"Understanding dementia and Alzheimer's","d":"What is happening, and what helps","href":"https://mo-care.com/guides/dementia-and-alzheimers"},{"t":"Fall prevention at home","d":"The changes that prevent the most falls","href":"https://mo-care.com/guides/fall-prevention-at-home"},{"t":"What happens at the free assessment","d":"60 to 90 minutes at home, no decision needed that day","href":"https://mo-care.com/before-your-assessment"}]}],"cta":{"label":"Talk With Us This Season","href":"https://mo-care.com/schedule-consultation","kind":"link"},"sign":"Merry Christmas from our family to yours,","aud":"monthly","key":"m23","banner":"h23","seg":"Holiday","footer":""},{"id":24,"photo":"scene-arrive-porch","month":"December","when":"Dec 27–31","cat":"Promo","ac":"#c79a3a","subj":"The gift that lasts long after the holidays","pre":"This year, give peace of mind.","eye":"Season's Greetings","head":"The best gift this year isn't under the tree","hero":"a warm winter window glowing with holiday lights","blocks":[{"t":"p","text":"As another year winds down, the gifts that matter most aren't wrapped, they're the comfort of knowing someone you love is safe, cared for, and not alone. That's a gift you can give all year long."},{"t":"p","text":"Whether it's a few companionship hours a week or hands-on daily care, we'll build a plan that fits your family, with no long-term contract and the freedom to change it anytime."},{"t":"p","text":"Thank you for letting us be part of so many Southwest Missouri families this year. Here's to a healthy, warm, and connected new year."},{"t":"links","head":"More that may help","items":[{"t":"Early Support Visits","d":"Help and good company, once a month or every other week","href":"https://mo-care.com/early-support-visits"},{"t":"Care cost calculator","d":"See what a week of care might cost","href":"https://mo-care.com/cost-calculator"},{"t":"What happens at the free assessment","d":"60 to 90 minutes at home, no decision needed that day","href":"https://mo-care.com/before-your-assessment"}]}],"cta":{"label":"Schedule a Free Consultation","href":"https://mo-care.com/schedule-consultation","kind":"link"},"sign":"Warm wishes for the new year,","aud":"monthly","key":"m24","banner":"h24","seg":"Promo","footer":""},{"id":30,"month":"Any time","when":"Send anytime","cat":"Helpful","ac":"#14606F","eye":"Early Support Visits","hero":"","subj":"Doing fine at home? A little help can still make a big difference","pre":"A helping hand and good company, once a month or every other week.","head":"You don't have to wait until more help is needed","photo":"scene-kitchen-coffee","blocks":[{"t":"p","text":"Mom is doing well at home. Dad still manages his day. But you wish someone could stop by regularly, lend a hand, and spend a little time with them."},{"t":"p","text":"That is why we created Early Support Visits. A caregiver from our team comes for a four-hour visit, once a month or every other week. A visit can include:"},{"t":"l","items":["Dishes, the kitchen and the counters","Laundry and fresh sheets on the bed","Sweeping, vacuuming and the bathroom","A meal made, with extra for later","An errand or a ride","Good company while it all gets done"]},{"t":"p","text":"It is often the right fit when:"},{"t":"l","items":["They are managing, but the house or the meals are slipping a little","You live far away, or work, and cannot stop by as often as you would like","They would say no to \"home care\" but would welcome a hand","You would like to hear how they are doing from someone who was just there"]},{"t":"p","text":"If your mom or dad would like, our office sends you a short note after each visit: what we helped with, how the visit went, and anything we noticed that seemed worth mentioning. For example: \"We changed the bed, made chicken soup and ran to the pharmacy today. Your mom was in great spirits and showed us her new quilt.\""},{"t":"p","text":"And if a harder season ever comes, maybe after a fall or an illness, you already have a team that knows your family."},{"t":"tip","text":"Early Support Visits are offered in Springfield: $152 a visit once a month, or $140 a visit every other week, on the same day and time each time. Before the first visit, someone from our office comes to get to know them and their home, for a one-time $99."},{"t":"links","head":"More that may help","items":[{"t":"Fall prevention at home","d":"Small changes that prevent the most common falls","href":"https://mo-care.com/guides/fall-prevention-at-home"},{"t":"Eating well as we age","d":"What to watch for when meals start slipping","href":"https://mo-care.com/guides/eating-well-as-we-age"},{"t":"Medication management","d":"Keeping pills straight, safely","href":"https://mo-care.com/guides/medication-management"}]}],"cta":{"label":"See how Early Support Visits work","href":"https://mo-care.com/early-support-visits","kind":"link"},"sign":"Warmly,","aud":"monthly","key":"m30"},{"id":31,"month":"Any time","when":"Send anytime","cat":"Helpful","ac":"#14606F","eye":"Care for Couples","hero":"","subj":"When Mom and Dad both need a hand","pre":"One caregiver can help them both, at home together.","head":"Help for both of you, at home together","photo":"scene-sofa-album","blocks":[{"t":"p","text":"Many couples have looked after each other for years. Often one of them is doing more than they should to care for the other, and both could use some help."},{"t":"p","text":"One caregiver can help them both in the same visit, so they stay side by side in their own home and their own routines. A visit can look like:"},{"t":"l","items":["A shower and getting dressed for one, a good lunch and company for the other","Laundry, dishes and the house kept up for both","Errands and rides to appointments","Medication reminders for each of them"]},{"t":"p","text":"Signs a couple could use a hand:"},{"t":"l","items":["One of them is doing lifting, bathing or night-time help that is no longer safe for them","The one doing the caring has stopped seeing friends, or has put off their own doctor","Meals have become whatever is easiest","If either of them fell or went into the hospital, the other could not manage alone"]},{"t":"p","text":"At the free assessment at home we sit down with you both, listen to what each of you needs, and tell you honestly what one caregiver can do in a visit. And the husband or wife who has been doing the caring gets to be a spouse again."},{"t":"tip","text":"Care for two often costs no more than care for one. When one of you needs personal care, the other still enjoys the cooking, cleaning and errands done for the household, at the regular hourly rate."},{"t":"links","head":"More that may help","items":[{"t":"Caregiver burnout","d":"For the spouse who is doing it all","href":"https://mo-care.com/guides/caregiver-burnout"},{"t":"Care cost calculator","d":"See what a week of care might cost","href":"https://mo-care.com/cost-calculator"},{"t":"What happens at the free assessment","d":"60 to 90 minutes at home, no decision needed that day","href":"https://mo-care.com/before-your-assessment"}]}],"cta":{"label":"See Care for Couples","href":"https://mo-care.com/services/care-for-couples","kind":"link"},"sign":"Warmly,","aud":"monthly","key":"m31"},{"id":32,"month":"Any time","when":"Send anytime","cat":"Helpful","ac":"#14606F","eye":"Care Wherever They Live","hero":"","subj":"Home is not always a house","pre":"One-on-one care in assisted living, rehab or the hospital.","head":"One-on-one care, wherever they are living","photo":"scene-puzzle","blocks":[{"t":"p","text":"The staff in a care community or a hospital look after many people at once, and they work hard. A caregiver from our team is there for one person: yours. We work alongside the staff and add time, attention and good company."},{"t":"l","items":["In assisted living or a nursing home: company, a hand at mealtimes, walks, help getting to activities, and a little extra personal attention during the day","In the hospital: someone at the bedside so they are not alone, and so you can go home and rest","During rehab: company and encouragement between therapy sessions"]},{"t":"p","text":"Families most often ask for this:"},{"t":"l","items":["In the first weeks after a move, while they settle in","When they are confused or anxious and calmer with someone beside them","When family lives far away or cannot visit as often as they would like","During a hospital stay, so someone is there when you cannot be"]},{"t":"p","text":"Our caregivers do not give medical care. The nurses and staff still do that. We are there for comfort, company and everyday help."},{"t":"tip","text":"You arrange it with us, the same way as care at home, and at the same hourly rates."},{"t":"links","head":"More that may help","items":[{"t":"Understanding dementia and Alzheimer's","d":"What is happening, and what helps","href":"https://mo-care.com/guides/dementia-and-alzheimers"},{"t":"Coming home after a hospital stay","d":"What to settle before discharge","href":"https://mo-care.com/guides/hospital-discharge"}]}],"cta":{"label":"See how it works","href":"https://mo-care.com/services/care-wherever-they-live","kind":"link"},"sign":"Warmly,","aud":"monthly","key":"m32"},{"id":33,"month":"Any time","when":"Send anytime","cat":"Helpful","ac":"#14606F","eye":"Hospital and Recovery","hero":"","subj":"The first few days home from the hospital","pre":"What to ask before discharge, and a checklist for the first 72 hours.","head":"Coming home is the goal. The first days are the hard part.","photo":"scene-door-handshake","blocks":[{"t":"p","text":"The first 72 hours home from the hospital carry the highest risk of complications or a trip back to the ER. A little preparation goes a long way."},{"t":"p","text":"Before discharge, ask the discharge planner:"},{"t":"l","items":["What follow-up appointments are needed, and when?","Which symptoms mean call the doctor, and which mean go to the ER?","What changed on the medication list?","Is any equipment needed at home, such as a walker or a shower chair?"]},{"t":"p","text":"The 72-hour checklist:"},{"t":"l","items":["New and existing medications on one list, with a pillbox if that helps","Follow-up appointments scheduled before leaving the hospital, not after","A clear path at home with nothing to trip on, especially to the bathroom","Someone available for the first 24 to 48 hours, even if only to check in","A plan for meals that does not rely on the person who just came home"]},{"t":"tip","text":"Call the doctor who discharged them, or go back to care right away, for new confusion, a fever, worsening pain, shortness of breath, or a fall. Do not wait for the next appointment."},{"t":"p","text":"Most families need help for a few weeks, not forever: medication reminders, help getting around safely, and someone who notices changes and tells you. Care can sometimes begin the same day or the next day, depending on caregiver availability."},{"t":"links","head":"More that may help","items":[{"t":"Coming home after a hospital stay","d":"The full guide, about a 6 minute read","href":"https://mo-care.com/guides/hospital-discharge"},{"t":"Fall prevention at home","d":"The changes that matter most","href":"https://mo-care.com/guides/fall-prevention-at-home"},{"t":"Medication management","d":"One list, and how to keep it right","href":"https://mo-care.com/guides/medication-management"}]}],"cta":{"label":"Read the guide","href":"https://mo-care.com/guides/hospital-discharge","kind":"link"},"sign":"Warmly,","aud":"monthly","key":"m33"},{"id":34,"month":"Any time","when":"Send anytime","cat":"Helpful","ac":"#14606F","eye":"Paying for Care","hero":"","subj":"What does home care really cost?","pre":"Our rates, how billing works, and the ways families pay.","head":"Clear pricing. No surprises.","photo":"scene-phone-together","blocks":[{"t":"p","text":"Finding the right care for someone you love is a big decision. Understanding the cost should not make it harder. So we publish our rates:"},{"t":"l","items":["Wellness Care, $30 an hour: company, meals, light housekeeping, errands and medication reminders","Personal Care, $32 an hour: all of that, plus hands-on help with bathing, dressing, toileting, walking and safe transfers","Advanced Care, $34 an hour: for advanced dementia, serious mobility limits and other complex needs"]},{"t":"p","text":"How billing works:"},{"t":"l","items":["No deposit and no long-term contract","You are billed weekly, after the visits have happened, from your caregiver's actual clock-in and clock-out times","Your rate is written in your agreement, and we give at least 4 weeks' written notice before any change","You can stop care when you need to"]},{"t":"p","text":"Ways families pay for it:"},{"t":"l","items":["Long-term care insurance: we review the policy with you and help with the claim","Veterans: we work with VA Community Care for eligible veterans","Dementia: Medicare's GUIDE program can cover 20 four-hour respite visits a year for families who meet its criteria","Families with active Medicaid? Our sister company, Caring Companions Consumer Directed Services, can help: caringcds.com or (417) 218-2888."]},{"t":"tip","text":"Best Price Guarantee: for new private-pay clients, we'll beat a comparable written rate from a professional home care agency for the first 6 months. Additional eligibility terms may apply."},{"t":"links","head":"See it for yourself","items":[{"t":"Care cost calculator","d":"What a week might cost, beside assisted living","href":"https://mo-care.com/cost-calculator"},{"t":"Long-term care insurance","d":"How we help you use a policy","href":"https://mo-care.com/long-term-care-insurance"},{"t":"The agreement our clients sign","d":"Read it before we ever meet","href":"https://mo-care.com/before-your-assessment"}]}],"cta":{"label":"Try the cost calculator","href":"https://mo-care.com/cost-calculator","kind":"link"},"sign":"Warmly,","aud":"monthly","key":"m34"},{"id":35,"month":"Any time","when":"Send anytime","cat":"Helpful","ac":"#14606F","eye":"Dementia Care","hero":"","subj":"Medicare may pay for a break you need","pre":"A program for families living with dementia at home.","head":"Caring for someone with dementia? Ask about GUIDE.","photo":"scene-tired","blocks":[{"t":"p","text":"GUIDE is a Medicare program for people living with dementia at home. Most eligible families never hear it exists."},{"t":"p","text":"Through a GUIDE program, families get:"},{"t":"l","items":["A dementia care navigator who calls you every month","A support line, any hour of the day or night","For families who meet Medicare's criteria, 20 four-hour respite visits a year, billed to Medicare and not to you"]},{"t":"p","text":"A respite visit is four hours when one of our caregivers is with your loved one, so you can rest, run errands, see a friend, or sleep. It may be time to ask if:"},{"t":"l","items":["You have not had a few hours to yourself in weeks","You are up with them at night and running on little sleep","You have put off your own doctor, or stopped seeing friends","You find yourself short-tempered, and feel bad about it afterward"]},{"t":"p","text":"Caring Companions is an approved GUIDE respite provider in southwest Missouri. Checking eligibility takes about two minutes, or call (417) 234-8494 and we will do it with you."},{"t":"links","head":"More that may help","items":[{"t":"The Dementia Journey","d":"A free nine-module course for families, no sign-up","href":"https://mo-care.com/family-academy"},{"t":"Best practices for dementia care","d":"What helps in the day to day","href":"https://mo-care.com/guides/best-practices-for-dementia-care"},{"t":"Caregiver burnout","d":"The signs, and what to do about them","href":"https://mo-care.com/guides/caregiver-burnout"}]}],"cta":{"label":"Check eligibility","href":"https://mo-care.com/medicare-guide","kind":"link"},"sign":"Warmly,","aud":"monthly","key":"m35"},{"id":36,"month":"Any time","when":"Send anytime","cat":"Helpful","ac":"#14606F","eye":"Paying for Care","hero":"","subj":"Is there a long-term care policy in a drawer somewhere?","pre":"It may pay for care at home, and we help with the claim.","head":"Put your long-term care policy to work, at home","photo":"scene-references","blocks":[{"t":"p","text":"If you or your loved one paid into a long-term care insurance policy, it may cover most or all of the cost of in-home care. Many families are not sure how to start a claim. Here is how it goes with us:"},{"t":"ol","items":["Find the policy and the insurance company's phone number.","Call us for a free review. We look at what the policy requires, its waiting period, the daily or monthly maximum, the lifetime benefit, and what is covered.","We set up a call with you and the insurance company.","We help you complete the claim forms.","Once the claim is approved, you choose: we bill the insurance company directly, or you pay us and send in our paid invoices to be reimbursed."]},{"t":"p","text":"Most policies pay once help is needed with two or more activities of daily living, such as bathing or dressing, or with a cognitive impairment."},{"t":"tip","text":"The policy review is free, before you commit to anything."},{"t":"links","head":"More that may help","items":[{"t":"How we help with long-term care insurance","d":"The two ways to use your benefits","href":"https://mo-care.com/long-term-care-insurance"},{"t":"What does home care cost?","d":"Our rates, published","href":"https://mo-care.com/pricing"},{"t":"VA benefits for home care","d":"For veterans and surviving spouses","href":"https://mo-care.com/guides/va-benefits-for-home-care"}]}],"cta":{"label":"See how we help","href":"https://mo-care.com/long-term-care-insurance","kind":"link"},"sign":"Warmly,","aud":"monthly","key":"m36"},{"id":37,"month":"Any time","when":"Send anytime","cat":"Helpful","ac":"#14606F","eye":"Our Caregivers","hero":"","subj":"Know who's coming before they knock","pre":"Meet your caregiver before the first visit.","head":"A face you already know, not a stranger","photo":"scene-profile-photo","blocks":[{"t":"p","text":"Letting someone into your home is a big step. Many families put help off for that reason alone."},{"t":"p","text":"Before the first visit, we text you and your family a private link to your caregiver's profile:"},{"t":"l","items":["A friendly photo","A little about them","Their experience","Why they love caregiving","For some caregivers, a short hello video"]},{"t":"p","text":"So when the doorbell rings, it is a face you already know."},{"t":"video","href":"https://mo-care.com/our-caregivers","img":"never-a-stranger","alt":"Never a Stranger","title":"Watch: Never a Stranger"},{"t":"p","text":"It starts earlier than that. The care coordinator who comes to your free assessment is named in your confirmation, with a link to their profile. And at that visit we ask who your loved one would like: preferences such as pets, smoking, language, or a man or a woman."},{"t":"tip","text":"Every caregiver has passed background checks and is trained before working in a client's home."},{"t":"links","head":"More that may help","items":[{"t":"Our caregivers","d":"Who comes to your door","href":"https://mo-care.com/our-caregivers"},{"t":"How our caregivers are trained","d":"What they learn before the first visit","href":"https://mo-care.com/our-caregivers-training"}]}],"cta":{"label":"See a sample profile","href":"https://mo-care.com/our-caregivers#meet-your-caregiver","kind":"link"},"sign":"Warmly,","aud":"monthly","key":"m37"},{"id":38,"month":"Any time","when":"Send anytime","cat":"Helpful","ac":"#14606F","eye":"Getting Started","hero":"","subj":"What happens at a free in-home assessment?","pre":"60 to 90 minutes at home, and no decision needed that day.","head":"Know how we work before we ever sit down together","photo":"scene-planning-talk","blocks":[{"t":"p","text":"A first visit should not feel like a sales call. Ours is free, takes 60 to 90 minutes at home, and you do not have to decide anything that day. Anyone you would like there is welcome, and your loved one's voice comes first."},{"t":"p","text":"What we talk about:"},{"t":"l","items":["Their story: routines, what they enjoy, and what has gotten harder lately","Health and medicines, so the care plan is safe","Everyday help: what they do on their own, and where a hand would help","Who they would like as a caregiver","Schedule, level of care and what a week would cost","Which family members should be kept in the loop"]},{"t":"p","text":"What you have when we leave:"},{"t":"l","items":["A care proposal in writing: the level we recommend and why, the days and hours, and the estimated weekly cost","Your own Client Handbook","A \"what happens next\" sheet, so the steps are clear"]},{"t":"tip","text":"Good to have handy: a list of medications, doctors' names and numbers, and any long-term care insurance policy."},{"t":"links","head":"Read it all ahead of time","items":[{"t":"Before your assessment","d":"Our rates, what caregivers can and cannot do, how billing works","href":"https://mo-care.com/before-your-assessment"},{"t":"Client Handbook","d":"How care works, billing, your rights and privacy","href":"https://mo-care.com/assets/docs/caring-companions-client-handbook.pdf"},{"t":"Sample Client Care Agreement","d":"The agreement our clients sign","href":"https://mo-care.com/assets/docs/caring-companions-client-care-agreement-sample.pdf"}]}],"cta":{"label":"See what to expect","href":"https://mo-care.com/before-your-assessment","kind":"link"},"sign":"Warmly,","aud":"monthly","key":"m38"},{"id":39,"month":"Any time","when":"Send anytime","cat":"Helpful","ac":"#14606F","eye":"Overnight Care","hero":"","subj":"When the nights are the hard part","pre":"Someone awake and there, from evening to morning.","head":"Someone there through the night","photo":"scene-evening-pills","blocks":[{"t":"p","text":"For many families the biggest worry is the hours between dinner and breakfast: a fall on the way to the bathroom, wandering, a confused wake-up at 3 a.m."},{"t":"p","text":"With Overnight Care, a caregiver comes in the evening and stays through the night, awake and ready to help with bathroom trips, wandering, medication reminders, or anything else that happens after dark. It is often the right fit for:"},{"t":"l","items":["Families most worried about night-time falls or wandering","Families who manage the days themselves but need to sleep","Someone just home from the hospital who should not be alone at night for a while"]},{"t":"p","text":"Three things that make nights safer, whoever is there:"},{"t":"l","items":["A clear, well-lit path to the bathroom","A nightlight","A phone or call button within arm's reach of the bed"]},{"t":"p","text":"When someone should not be alone at any hour, 24-Hour Care keeps a caregiver there day and night, in shifts."},{"t":"tip","text":"Overnight Care is scheduled as 8 to 12 hour shifts, evening to morning, as many nights a week as you need, at our regular rates of $30 to $34 an hour."},{"t":"links","head":"More that may help","items":[{"t":"Fall prevention at home","d":"The changes that prevent the most falls","href":"https://mo-care.com/guides/fall-prevention-at-home"},{"t":"Understanding dementia and Alzheimer's","d":"Why nights get harder, and what helps","href":"https://mo-care.com/guides/dementia-and-alzheimers"},{"t":"24-Hour Care","d":"When someone is needed around the clock","href":"https://mo-care.com/services/24-hour-care"}]}],"cta":{"label":"See Overnight Care","href":"https://mo-care.com/services/overnight-care","kind":"link"},"sign":"Warmly,","aud":"monthly","key":"m39"},{"id":40,"month":"Any time","when":"Send anytime","cat":"Helpful","ac":"#14606F","eye":"End-of-Life Care","hero":"","subj":"Hospice visits. Who is there the rest of the day?","pre":"Care at home, alongside your hospice team.","head":"So your loved one is not alone, and you can rest","photo":"scene-hands","blocks":[{"t":"p","text":"When someone chooses hospice at home, a hospice team takes charge of comfort: nurses, aides, medicine for pain and symptoms, equipment, and someone to call day or night. It is a relief for many families."},{"t":"p","text":"What surprises families is how many hours are still theirs to cover. Hospice visits, but it usually does not stay. Ask your hospice team exactly how often they will visit."},{"t":"p","text":"That is where we come in. Our caregivers work alongside the hospice team. A week of help can look like three overnights so the family can sleep, or mornings on weekdays while family works:"},{"t":"l","items":["Sitting with them, talking, reading or playing their music","Gentle help with bathing, changing and keeping them clean and comfortable","Small meals or sips of whatever they want","Laundry, and keeping the house quiet and calm","Being there overnight so someone is always awake"]},{"t":"p","text":"You get to be a daughter, a son or a spouse, and not only the caregiver."},{"t":"tip","text":"If you have not talked about their wishes yet, \"What matters most to you if things get harder?\" opens the door more gently than starting with paperwork. There is no perfect time, only earlier and later, and earlier is almost always better."},{"t":"links","head":"More that may help","items":[{"t":"Home care alongside hospice","d":"What hospice covers, and what it does not","href":"https://mo-care.com/guides/planning-for-end-of-life-care"},{"t":"Caregiver burnout","d":"Looking after yourself in a hard season","href":"https://mo-care.com/guides/caregiver-burnout"}]}],"cta":{"label":"Read: Home Care Alongside Hospice","href":"https://mo-care.com/guides/planning-for-end-of-life-care","kind":"link"},"sign":"Warmly,","aud":"monthly","key":"m40"},{"id":41,"month":"Any time","when":"Send anytime","cat":"Helpful","ac":"#14606F","eye":"Family Guides","hero":"","subj":"Short, honest reads for the questions you're facing","pre":"Family Guides and a full dementia course, with no sign-up.","head":"Start where you are","photo":"scene-daughter-text","blocks":[{"t":"p","text":"Our Family Guides are short, honest reads on the questions families face, written by our team in Springfield from what we see in families' homes every week. Start with the one that fits today."},{"t":"links","head":"Something seems off with Mom or Dad","items":[{"t":"Understanding dementia and Alzheimer's","d":"What is happening, and what helps","href":"https://mo-care.com/guides/dementia-and-alzheimers"},{"t":"Fall prevention at home","d":"The changes that matter most","href":"https://mo-care.com/guides/fall-prevention-at-home"},{"t":"Eating well as we age","d":"When meals start slipping","href":"https://mo-care.com/guides/eating-well-as-we-age"}]},{"t":"links","head":"Someone is coming home from the hospital","items":[{"t":"Coming home after a hospital stay","d":"What to ask, and a 72-hour checklist","href":"https://mo-care.com/guides/hospital-discharge"},{"t":"Stroke recovery at home","d":"The first weeks and months","href":"https://mo-care.com/guides/stroke-recovery-at-home"},{"t":"Medication management","d":"One list, kept right","href":"https://mo-care.com/guides/medication-management"}]},{"t":"links","head":"Living with a long-term condition","items":[{"t":"Living well with heart failure","d":"Daily habits that help","href":"https://mo-care.com/guides/living-well-with-heart-failure"},{"t":"Managing COPD at home","d":"Breathing easier day to day","href":"https://mo-care.com/guides/managing-copd-at-home"},{"t":"Parkinson's disease at home","d":"Staying safe and independent","href":"https://mo-care.com/guides/parkinsons-disease-at-home"}]},{"t":"links","head":"You are worn out, or working out how to pay","items":[{"t":"Caregiver burnout","d":"The signs, and what to do","href":"https://mo-care.com/guides/caregiver-burnout"},{"t":"Home health or home care?","d":"What each one is, and who pays","href":"https://mo-care.com/guides/home-health-vs-home-care"},{"t":"VA benefits for home care","d":"For veterans and surviving spouses","href":"https://mo-care.com/guides/va-benefits-for-home-care"}]},{"t":"p","text":"And if you are caring for someone with dementia, The Dementia Journey is a nine-module course built just for families, narrated by Samantha. It is free, there is no sign-up, and every module is open: mo-care.com/family-academy"}],"cta":{"label":"Browse the Family Guides","href":"https://mo-care.com/resource-library","kind":"link"},"sign":"Warmly,","aud":"monthly","key":"m41"},{"id":5,"photo":"scene-training","month":"January","when":"Early January","cat":"Holiday","ac":"#4f8f74","banner":"h1","eye":"Happy New Year","hero":"new year wishes for the team","subj":"Happy New Year to our incredible team","pre":"Here's to you, and the year ahead.","head":"Wishing you a happy and healthy New Year","blocks":[{"t":"p","text":"As a new year begins, we want to say thank you. The compassion you bring into our clients' homes changes lives, and you are what makes Caring Companions what it is."},{"t":"p","text":"Here's to a year of good health, good shifts, and feeling appreciated for the essential work you do."}],"cta":{"label":"Reach the Office · (417) 234-8494","href":"tel:4172348494","kind":"call"},"sign":"With gratitude,","aud":"caregivers","key":"g5","seg":"Holiday","footer":""},{"id":6,"photo":"hero-caregiver","month":"February","when":"Feb 7–13","cat":"Holiday","ac":"#b9694a","banner":"h3","eye":"Valentine's Day","hero":"valentine appreciation for caregivers","subj":"You bring so much heart to this work","pre":"A little Valentine's thank-you for our caregivers.","head":"This Valentine's Day, we're celebrating you","blocks":[{"t":"p","text":"Valentine's Day is about heart, and few people give more of theirs than our caregivers. The warmth, patience, and kindness you show our clients is the truest kind of love there is."},{"t":"p","text":"Thank you for the heart you bring to work every day. We're so grateful for you."}],"cta":{"label":"Reach the Office · (417) 234-8494","href":"tel:4172348494","kind":"call"},"sign":"With appreciation,","aud":"caregivers","key":"g6","seg":"Holiday","footer":""},{"id":7,"photo":"scene-garden-visit","month":"July","when":"June 30–July 3","cat":"Holiday","ac":"#5d7896","banner":"h13","eye":"Independence Day","hero":"independence day thank-you","subj":"Happy 4th of July, and thank you","pre":"A holiday thank-you to those caring for others.","head":"Wishing you a happy Independence Day","blocks":[{"t":"p","text":"Happy Fourth of July! Whether you're off enjoying the holiday or working to keep our clients safe and cared for, we're thinking of you and grateful for you."},{"t":"tip","text":"Covering a holiday shift? Thank you, truly. Reach out to the office anytime if you need anything while you're on."}],"cta":{"label":"Reach the Office · (417) 234-8494","href":"tel:4172348494","kind":"call"},"sign":"With thanks,","aud":"caregivers","key":"g7","seg":"Holiday","footer":""},{"id":8,"photo":"scene-kitchen-coffee","month":"November","when":"Nov 20–27","cat":"Holiday","ac":"#b9694a","banner":"h21","eye":"Thanksgiving","hero":"thanksgiving gratitude for caregivers","subj":"This Thanksgiving, we're thankful for you","pre":"Our caregivers are at the top of our gratitude list.","head":"Grateful for you this Thanksgiving","blocks":[{"t":"p","text":"When we count our blessings this Thanksgiving, our caregivers are right at the top of the list. The comfort and dignity you bring to our clients is a gift to entire families."},{"t":"p","text":"Thank you for all you do, especially in a season when your care means even more. Happy Thanksgiving."}],"cta":{"label":"Reach the Office · (417) 234-8494","href":"tel:4172348494","kind":"call"},"sign":"With a grateful heart,","aud":"caregivers","key":"g8","seg":"Holiday","footer":""},{"id":9,"photo":"hero-caregiver-sofa","month":"December","when":"Dec 18–24","cat":"Holiday","ac":"#4f8f74","banner":"h23","eye":"Happy Holidays","hero":"holiday warmth for the team","subj":"Happy holidays to our caregiving family","pre":"Warm wishes, and thanks for the shifts that matter most.","head":"Wishing you a warm and joyful holiday season","blocks":[{"t":"p","text":"From all of us at Caring Companions, happy holidays! We hope your season is filled with rest, warmth, and the people you love."},{"t":"tip","text":"To everyone covering holiday shifts so our clients aren't alone, thank you. It's one of the most meaningful things anyone can do, and we don't take it for granted."}],"cta":{"label":"Reach the Office · (417) 234-8494","href":"tel:4172348494","kind":"call"},"sign":"With love and gratitude,","aud":"caregivers","key":"g9","seg":"Holiday","footer":""},{"id":39,"month":"Any Referral Partner","when":"Partner series · 1","cat":"Partner series","ac":"#14606F","eye":"Why families can trust the referral","hero":"","subj":"Home care your families can check before they call","pre":"Our rates, our agreement and our handbook are all public.","head":"Nothing about our care is hidden until the sales visit","blocks":[{"t":"p","text":"When you suggest a home care agency, the family's first questions are about cost and commitment. With Caring Companions they can answer both before they ever call us."},{"t":"stats","items":[{"big":"$30 to $34","small":"an hour, published on our website"},{"big":"4.9 <span style=\"color:#A88400;\">&#9733;</span>","small":"on Google, from families we serve"},{"big":"Since 2017","small":"locally owned, not a franchise"}]},{"t":"l","items":["No deposit and no long-term contract","The <a href=\"https://mo-care.com/assets/docs/caring-companions-client-handbook.pdf\" style=\"color:#14606F;font-weight:700;\">Client Handbook</a> and the <a href=\"https://mo-care.com/assets/docs/caring-companions-client-care-agreement-sample.pdf\" style=\"color:#14606F;font-weight:700;\">agreement our clients sign</a> are on our website to read first","The assessment is free, 60 to 90 minutes at home, and the family keeps everything in writing"]},{"t":"links","head":"See it for yourself","text":"Everything a family will see is open to you too. Read it before you ever mention our name.","items":[{"t":"Sample Client Care Agreement","d":"The agreement our clients sign, with the rate sheet. PDF.","href":"https://mo-care.com/assets/docs/caring-companions-client-care-agreement-sample.pdf"},{"t":"Client Handbook","d":"How care works, billing, and a client's rights and privacy. PDF.","href":"https://mo-care.com/assets/docs/caring-companions-client-handbook.pdf"},{"t":"Our rates","d":"Every rate, the minimums and the Best Price Guarantee.","href":"https://mo-care.com/pricing"},{"t":"A sample caregiver profile","d":"What a family is sent before the first visit.","href":"https://mo-care.com/our-caregivers#meet-your-caregiver"},{"t":"How we decide","d":"How we recommend a level of care, and when we say home care is not the answer.","href":"https://mo-care.com/how-we-decide"},{"t":"Care cost calculator","d":"Home care beside assisted living and nursing home costs.","href":"https://mo-care.com/cost-calculator"}]}],"cta":{"label":"See what families see","href":"https://mo-care.com/before-your-assessment","kind":"link"},"sign":"From our Springfield office,","seg":"Any Referral Partner","series":1,"openers":{"Hospice & Palliative":"Your team manages comfort. The hours between your visits are the part we cover.","Home Health":"When your skilled visits end, most patients still need help with the day. That is the part we do.","Skilled Nursing & Rehab":"A discharge home holds when someone is there to help in the first weeks.","Hospitals & Case Mgmt":"When a patient is going home and the family asks who can help, this is what you can tell them about us.","Senior Living":"When a resident needs more one-on-one time than your staffing allows, our caregivers come to them in your community.","Physicians & Clinics":"Some patients are medically stable and still not managing at home. A few hours of help a week changes that.","Elder Law & Financial":"When your clients ask who to trust for care at home, cost and commitment are their first questions."},"aud":"referrers","key":"r39"},{"id":40,"month":"Any Referral Partner","when":"Partner series · 2","cat":"Partner series","ac":"#14606F","eye":"Why families can trust the referral","hero":"","subj":"Your patients see who is coming before the doorbell rings","pre":"A photo, a story and the caregiver's experience, sent ahead.","head":"Never a stranger at the door","blocks":[{"t":"p","text":"The hardest part of accepting help is letting someone new into the house. Many families put care off for that reason alone."},{"t":"p","text":"Before a first visit, we text the client and family a private link to their caregiver's profile: a photo, a little about them, their experience, and why they do this work. Some caregivers add a short hello video. When the doorbell rings, it is a face they already know."},{"t":"video","href":"https://mo-care.com/our-caregivers#meet-your-caregiver","img":"never-a-stranger","alt":"Never a Stranger: a short video about meeting your caregiver before the first visit","title":"Watch: Never a Stranger","caption":"How a family meets their caregiver before the first visit."},{"t":"p","text":"Every caregiver has passed background checks and is trained before working in a client's home."}],"cta":{"label":"See a sample profile","href":"https://mo-care.com/our-caregivers#meet-your-caregiver","kind":"link"},"sign":"From our Springfield office,","seg":"Any Referral Partner","series":2,"aud":"referrers","key":"r40"},{"id":41,"month":"Any Referral Partner","when":"Partner series · 3","cat":"Partner series","ac":"#14606F","eye":"Know what you are referring to","hero":"","subj":"What our caregivers do, and what they don't","pre":"Three levels of non-medical care, with clear limits.","head":"You should know exactly what you are referring to","blocks":[{"t":"p","text":"We provide non-medical care at three levels, and we tell families which one fits at the assessment:"},{"t":"l","items":["Wellness Care: company, meals, light housekeeping, errands and medication reminders","Personal Care: all of that, plus hands-on help with bathing, dressing, toileting and transfers","Advanced Care: more experienced caregivers for advanced dementia and complex mobility needs"]},{"t":"p","text":"The same levels are available overnight and around the clock."},{"t":"p","text":"We are just as clear about the limits. Our caregivers remind clients to take medications. They do not fill pill organizers, check blood sugar, give insulin or handle oxygen. In an emergency they call 911, then our office. That clarity is why clinical teams can work alongside us without wondering who is doing what."}],"cta":{"label":"See each level","href":"https://mo-care.com/our-services","kind":"link"},"sign":"From our Springfield office,","seg":"Any Referral Partner","series":3,"aud":"referrers","key":"r41"},{"id":42,"month":"Any Referral Partner","when":"Partner series · 4","cat":"Partner series","ac":"#14606F","eye":"Paying for care","hero":"","subj":"\"How will we pay for it?\" We do the work on that question.","pre":"Long-term care insurance, VA, Medicare GUIDE and open private rates.","head":"A referral only helps if the family can afford to act on it","blocks":[{"t":"p","text":"Cost is where most care plans stall. Here is what we take off the family's plate:"},{"t":"l","items":["Long-term care insurance: we review the policy with them, set up the call with the insurer and help with the claim forms. Depending on the policy, we may be able to bill the insurer directly.","Veterans: we work with VA Community Care for eligible veterans.","Dementia: we are an approved Medicare GUIDE respite provider in southwest Missouri. Families who meet Medicare's criteria can receive 20 four-hour respite visits a year, billed to Medicare.","Private pay: $30, $32 or $34 an hour, published, with a Best Price Guarantee for new private-pay clients. Eligibility terms apply.","Families with active Medicaid? Our sister company, Caring Companions Consumer Directed Services, can help: caringcds.com or (417) 218-2888."]}],"cta":{"label":"See ways to pay","href":"https://mo-care.com/pricing","kind":"link"},"sign":"From our Springfield office,","seg":"Any Referral Partner","series":4,"aud":"referrers","key":"r42"},{"id":43,"month":"Any Referral Partner","when":"Partner series · 5","cat":"Partner series","ac":"#14606F","eye":"More than a standard care plan","hero":"","subj":"Three situations we have an answer for","pre":"The person who needs very little, the couple, and the one who isn't at home.","head":"Not every referral fits a standard care plan","blocks":[{"t":"p","text":"Some of the people you see don't fit the usual picture of home care. We built for them too."},{"t":"l","items":["The person who says \"I don't need much.\" Early Support Visits are four-hour visits once a month or every other week, in Springfield: a hand around the house and good company. $152 a visit monthly, $140 every other week.","The couple. One caregiver can help both spouses in the same visit, so they stay together at home.","The person who isn't at home. Our caregivers also give one-on-one care in assisted living, nursing homes, rehab and the hospital, alongside the staff."]}],"cta":{"label":"See all services","href":"https://mo-care.com/our-services","kind":"link"},"sign":"From our Springfield office,","seg":"Any Referral Partner","series":5,"aud":"referrers","key":"r43"},{"id":44,"month":"Any Referral Partner","when":"Partner series · 6","cat":"Partner series","ac":"#14606F","eye":"How a referral works","hero":"","subj":"Referring takes two minutes. Here is what happens next.","pre":"One form, one call to the family, one visit at home.","head":"What happens after you send us a name","blocks":[{"t":"ol","items":["You send the referral: our secure online form, a call to (417) 234-8494, or a fax to (417) 719-7870.","A care coordinator from our Springfield office calls the family, usually the same business day.","We visit them at home for a free assessment and write the care plan with them.","Care can sometimes begin the same day or the next day, depending on caregiver availability."]},{"t":"p","text":"You don't need to qualify the family or explain our prices. Send us the name, and we take it from there."}],"cta":{"label":"Refer a patient","href":"https://mo-care.com/refer","kind":"link"},"sign":"From our Springfield office,","seg":"Any Referral Partner","series":6,"aud":"referrers","key":"r44"},{"id":45,"month":"Any Referral Partner","when":"After a referral","cat":"Partner series","ac":"#14606F","eye":"Your referral","hero":"","subj":"We have your referral. Here is what happens now.","pre":"A coordinator is calling the family.","head":"Your referral is with a care coordinator","blocks":[{"t":"p","text":"We received your referral, and a care coordinator from our Springfield office is contacting the family."},{"t":"p","text":"From here we offer them a free assessment at home, recommend a level of care, and put everything in writing before they decide anything. If home care with us is not the right answer for them, we will tell them so."},{"t":"p","text":"If you have questions about this family or another one, call our office at (417) 234-8494."}],"cta":{"label":"Call (417) 234-8494","href":"tel:4172348494","kind":"call"},"sign":"From our Springfield office,","seg":"Any Referral Partner","aud":"referrers","key":"r45"},{"id":5,"month":"January","when":"Early January","cat":"Holiday","ac":"#4f8f74","banner":"h1","eye":"Happy New Year","hero":"new year wishes","photo":"scene-kitchen-coffee","subj":"Happy New Year from all of us","pre":"Here's to a year of comfort and good company.","head":"Wishing you a warm and happy New Year","blocks":[{"t":"p","text":"From your whole Caring Companions family, happy New Year! We feel lucky to start another year alongside you, and we're looking forward to all the ordinary, wonderful days ahead."},{"t":"p","text":"Here's to a year filled with comfort, good company, and feeling right at home, because that's exactly what you deserve."}],"cta":{"label":"Call Us Anytime · (417) 234-8494","href":"tel:4172348494","kind":"call"},"sign":"With love,","aud":"clients","key":"c5a","seg":"Holiday","footer":"","variant":"To the client"},{"id":5,"month":"January","when":"Early January","cat":"Holiday","ac":"#4f8f74","banner":"h1","eye":"Happy New Year","hero":"new year wishes","photo":"scene-phone-together","subj":"Happy New Year, thank you for trusting us","pre":"Grateful to care for your loved one another year.","head":"Wishing your family a happy and healthy New Year","blocks":[{"t":"p","text":"As a new year begins, we want to say thank you. Trusting us with someone you love is no small thing, and we don't take it for granted."},{"t":"p","text":"Here's to a healthy, comfortable year ahead for your loved one, and please remember, as their needs change, we can grow their care right along with them."},{"t":"tip","text":"A new year is a natural time to revisit the care plan. If you'd like to talk through any adjustments, we're just a call away."}],"cta":{"label":"Call Us · (417) 234-8494","href":"tel:4172348494","kind":"call"},"sign":"With gratitude,","aud":"client_contacts","key":"c5b","seg":"Holiday","footer":"","variant":"To the family contact"},{"id":6,"month":"February","when":"Feb 7–13","cat":"Holiday","ac":"#b9694a","banner":"h3","eye":"Valentine's Day","hero":"valentine warmth","photo":"hero-caregiver-sofa","subj":"You're family to us","pre":"A little Valentine's note, just for you.","head":"This Valentine's Day, we're thinking of you","blocks":[{"t":"p","text":"Valentine's Day is about the people who fill our lives with warmth, and you're one of those people for us. It's a joy to spend our days with you."},{"t":"p","text":"Thank you for your stories, your smiles, and for letting us be part of your life. Happy Valentine's Day."}],"cta":{"label":"We're Always Just a Call Away","href":"tel:4172348494","kind":"call"},"sign":"With love,","aud":"clients","key":"c6a","seg":"Holiday","footer":"","variant":"To the client"},{"id":6,"month":"February","when":"Feb 7–13","cat":"Holiday","ac":"#b9694a","banner":"h3","eye":"Valentine's Day","hero":"valentine warmth","photo":"scene-home-hug","subj":"Thinking of your loved one this Valentine's Day","pre":"A note of appreciation, and a gentle thought.","head":"Sending a little extra warmth this Valentine's","blocks":[{"t":"p","text":"This Valentine's Day, we're grateful for the chance to care for someone you love. We hope they feel the warmth and companionship of the season."},{"t":"tip","text":"If your loved one ever feels lonely between visits, especially in these quieter winter months, a few extra companionship hours can brighten their days. Just say the word."}],"cta":{"label":"Add a Little Extra Company","href":"tel:4172348494","kind":"call"},"sign":"With warm regards,","aud":"client_contacts","key":"c6b","seg":"Holiday","footer":"","variant":"To the family contact"},{"id":7,"month":"July","when":"June 30–July 3","cat":"Holiday","ac":"#5d7896","banner":"h13","eye":"Independence Day","hero":"independence day wishes","photo":"scene-garden-visit","subj":"Happy 4th of July!","pre":"Warm wishes for a safe, happy holiday.","head":"Wishing you a happy Independence Day","blocks":[{"t":"p","text":"Happy Fourth of July! We hope your day is filled with good food, familiar faces, and a little celebration. However you spend it, know we're thinking of you."},{"t":"p","text":"And as the summer heats up, please remember to stay cool and hydrated, your caregiver is always here to help."}],"cta":{"label":"Call Us Anytime · (417) 234-8494","href":"tel:4172348494","kind":"call"},"sign":"With warm wishes,","aud":"clients","key":"c7a","seg":"Holiday","footer":"","variant":"To the client"},{"id":7,"month":"July","when":"June 30–July 3","cat":"Holiday","ac":"#5d7896","banner":"h13","eye":"Independence Day","hero":"independence day wishes","photo":"scene-garden-walker","subj":"Happy 4th, and a note on holiday support","pre":"Holiday wishes and support options.","head":"Wishing your family a happy Independence Day","blocks":[{"t":"p","text":"Happy Fourth of July from all of us! We hope your family enjoys a wonderful holiday together."},{"t":"tip","text":"Traveling or hosting this summer? We can add hours, overnight, or respite care so your loved one stays safe and comfortable, and you can relax. Just let us know."},{"t":"p","text":"Our caregivers are also keeping a close eye on summer heat and hydration for your loved one."}],"cta":{"label":"Ask About Extra Summer Support","href":"tel:4172348494","kind":"call"},"sign":"With warm wishes,","aud":"client_contacts","key":"c7b","seg":"Holiday","footer":"","variant":"To the family contact"},{"id":8,"month":"November","when":"Nov 20–27","cat":"Holiday","ac":"#b9694a","banner":"h21","eye":"Thanksgiving","hero":"thanksgiving gratitude","photo":"scene-sofa-album","subj":"We're thankful for you","pre":"A Thanksgiving note from your care team.","head":"This Thanksgiving, we're grateful for you","blocks":[{"t":"p","text":"When we count our blessings this Thanksgiving, you're near the top of the list. It's a true gift to spend our days with you, and we're thankful for every moment."},{"t":"p","text":"We hope your holiday is warm, comfortable, and full of the people and things you love."}],"cta":{"label":"We're Always Just a Call Away","href":"tel:4172348494","kind":"call"},"sign":"With a grateful heart,","aud":"clients","key":"c8a","seg":"Holiday","footer":"","variant":"To the client"},{"id":8,"month":"November","when":"Nov 20–27","cat":"Holiday","ac":"#b9694a","banner":"h21","eye":"Thanksgiving","hero":"thanksgiving gratitude","photo":"scene-welcome-porch","subj":"Grateful to care for your loved one this Thanksgiving","pre":"Thank you, and a little holiday help if you need it.","head":"This Thanksgiving, thank you for trusting us","blocks":[{"t":"p","text":"This season of gratitude, we want you to know how thankful we are for the trust you place in us to care for someone so important to your family."},{"t":"tip","text":"Hosting, traveling, or simply stretched thin this Thanksgiving? Extra caregiver hours or respite can lighten the load so you can be present with your family. We'd be glad to help."}],"cta":{"label":"Add Holiday Support","href":"tel:4172348494","kind":"call"},"sign":"With gratitude,","aud":"client_contacts","key":"c8b","seg":"Holiday","footer":"","variant":"To the family contact"},{"id":9,"month":"December","when":"Dec 18–24","cat":"Holiday","ac":"#4f8f74","banner":"h23","eye":"Happy Holidays","hero":"holiday warmth","photo":"hero-caregiver","subj":"Merry Christmas and happy holidays","pre":"Warm wishes for a cozy, joyful season.","head":"Wishing you a warm and joyful holiday season","blocks":[{"t":"p","text":"From all of us at Caring Companions, we're wishing you the merriest, coziest holiday season. May your days be filled with warmth, good memories, and the people who love you."},{"t":"p","text":"And if the season ever feels quiet, remember, you're never alone. We're always just a phone call away."}],"cta":{"label":"Call Us Anytime · (417) 234-8494","href":"tel:4172348494","kind":"call"},"sign":"With love and warm wishes,","aud":"clients","key":"c9a","seg":"Holiday","footer":"","variant":"To the client"},{"id":9,"month":"December","when":"Dec 18–24","cat":"Holiday","ac":"#4f8f74","banner":"h23","eye":"Happy Holidays","hero":"holiday warmth","photo":"scene-album-dad","subj":"Warm holiday wishes, and a little extra help if you need it","pre":"Season's greetings and holiday support options.","head":"Happy holidays from your loved one's care team","blocks":[{"t":"p","text":"Wishing your whole family a warm and joyful holiday season. It's been our honor to care for your loved one this year."},{"t":"tip","text":"The holidays can be a lot, hosting, traveling, extra visitors. If you'd like additional hours, overnight care, or respite so everyone can enjoy the season, we care for families right through the holidays. The earlier you let us know, the better we can plan."},{"t":"p","text":"Whatever you need, we're here. Merry Christmas and happy holidays."}],"cta":{"label":"Arrange Extra Holiday Care","href":"tel:4172348494","kind":"call"},"sign":"With warm wishes,","aud":"client_contacts","key":"c9b","seg":"Holiday","footer":"","variant":"To the family contact"},{"id":11,"month":"November","when":"Early November","cat":"Program","ac":"#b9694a","banner":"h19","eye":"Holiday Support","hero":"extra holiday support","photo":"scene-puzzle","subj":"Want a little extra company this season?","pre":"More help is here whenever you'd like it.","head":"The holidays are merrier with company","blocks":[{"t":"p","text":"The holidays can be busy and bright, or sometimes just a bit quiet. Whichever they are for you this year, we'd love to make them warmer."},{"t":"p","text":"If you'd enjoy some extra company, a hand with holiday cooking, help getting to gatherings, or just a few more visits, all you have to do is ask. We're here for you."}],"cta":{"label":"Just Say the Word","href":"tel:4172348494","kind":"call"},"sign":"With love,","aud":"clients","key":"c11a","seg":"Program","footer":"","variant":"To the client"},{"id":11,"month":"November","when":"Early November","cat":"Program","ac":"#b9694a","banner":"h19","eye":"Holiday Support","hero":"extra holiday support","photo":"scene-mom-waiting","subj":"Extra support for your loved one this holiday season","pre":"Add hours, overnight, or respite. Let us know early.","head":"A little extra help can make the holidays easier","blocks":[{"t":"p","text":"The holidays often bring more to juggle, travel, hosting, visitors, and a busier schedule for everyone. They can also be a lonelier, more disorienting time for older adults."},{"t":"p","text":"We're here to help however you need. A few options families love this time of year:"},{"t":"l","items":["Extra daytime hours for company and holiday prep","Overnight or 24-hour care while you travel or host","Respite care so the whole family can be present","Transportation to gatherings and appointments"]},{"t":"tip","text":"Caregivers book up quickly around the holidays, the earlier you let us know, the better we can plan."}],"cta":{"label":"Arrange Holiday Support","href":"tel:4172348494","kind":"call"},"sign":"With warm regards,","aud":"client_contacts","key":"c11b","seg":"Program","footer":"","variant":"To the family contact"},{"id":12,"month":"Anytime","when":"Send anytime","cat":"Program","ac":"#5d7896","banner":"h5","eye":"Did You Know?","hero":"more ways we can help","photo":"scene-kitchen-walker","subj":"A few more ways we're here for you","pre":"Did you know we can help with all of this?","head":"More ways we can help, whenever you need","blocks":[{"t":"p","text":"You may know us for the help you receive today, but there's a lot more we can do whenever you'd like. We're always ready to do more, never less."},{"t":"l","items":["Rides to appointments, errands, and the store","Help with meals, light housekeeping, and laundry","A nurse visit for medication management","Bathing, dressing, and personal care support"]},{"t":"p","text":"If any of these would make life easier, just mention it to your caregiver or give us a call."}],"cta":{"label":"Call Us Anytime · (417) 234-8494","href":"tel:4172348494","kind":"call"},"sign":"Warmly,","aud":"clients","key":"c12a","seg":"Program","footer":"","variant":"To the client"},{"id":12,"month":"Anytime","when":"Send anytime","cat":"Program","ac":"#5d7896","banner":"h5","eye":"Did You Know?","hero":"more ways we can help","photo":"scene-planning-talk","subj":"Did you know we offer all of this?","pre":"Care that can grow with your loved one's needs.","head":"More ways we can support your loved one","blocks":[{"t":"p","text":"As your loved one's needs change, their care can change right along with them, no new agency, no starting over. Here are some of the ways we can do more:"},{"t":"l","items":["Private-duty nursing and medication management","Personal care, bathing, dressing, mobility","Respite care to support family caregivers","Help at home after a hospital stay or illness","Care for dementia, Parkinson's, and more","VA, Medicare GUIDE, and long-term care insurance options","Have active Medicaid? Our sister company, Caring Companions Consumer Directed Services, can help: caringcds.com or (417) 218-2888."]},{"t":"tip","text":"Noticing your loved one needs a little more lately? Let's revisit the plan, we'll make it seamless."}],"cta":{"label":"Explore More Services","href":"https://mo-care.com/our-services","kind":"link"},"sign":"Warmly,","aud":"client_contacts","key":"c12b","seg":"Program","footer":"","variant":"To the family contact"},{"id":1,"photo":"scene-planning-talk","month":"VA leads","when":"VA series · 1","cat":"VA series","ac":"#14606F","eye":"VA benefits and care at home · 1 of 12","hero":"","subj":"The 4 ways the VA pays for help at home (most families know one)","pre":"A short map, so you know which door to knock on.","head":"The four ways the VA helps a veteran at home","blocks":[{"t":"p","text":"We are Caring Companions, a home care agency in Springfield, in network with the VA Community Care Network. Once a month we will send you one useful guide about VA benefits and care at home. This first one is the map."},{"t":"p","text":"There is no single \"VA home care program.\" There are four, and they work very differently."},{"t":"p","text":"<strong>1. Homemaker and Home Health Aide care.</strong> A caregiver from an agency like ours comes to the home and helps with bathing, dressing, meals and daily life. The VA authorizes it and pays the agency directly. It is based on what the veteran needs, not on income. This is the one most families have never heard of."},{"t":"p","text":"<strong>2. Aid and Attendance.</strong> Extra monthly money added to a VA pension, paid to the veteran or surviving spouse, who can use it to pay for care. It is based on wartime service, need for help, and limited income and assets."},{"t":"p","text":"<strong>3. VA caregiver programs.</strong> Support, training and, for some, a monthly stipend paid by the VA to a family member who cares for a veteran with a serious service-connected condition."},{"t":"p","text":"<strong>4. Veteran Directed Care.</strong> The VA gives the veteran a budget to hire their own help. It is offered only through some VA medical centers."},{"t":"p","text":"A veteran can sometimes use more than one. Over the next months we will take each one apart: who qualifies, how to apply, and where families get stuck."},{"t":"p","text":"If you want to know today which door fits your family, call our office. We will tell you honestly, even when the answer is not us."},{"t":"p","text":"<span style=\"font-size:14px;color:#5b6b7a;\">VA rules change, and your VA care team has the final word on what you qualify for.</span>"}],"cta":{"label":"See how VA home care works","href":"https://mo-care.com/veterans","kind":"link"},"sign":"From our Springfield office,","seg":"VA leads","series":1,"footer":"You're receiving this because we share VA home care information with veterans and their families in Missouri. We send one email a month.","aud":"va","key":"v1"},{"id":2,"photo":"scene-phone-together","month":"VA leads","when":"VA series · 2","cat":"VA series","ac":"#14606F","eye":"VA benefits and care at home · 2 of 12","hero":"","subj":"Before any VA home care: the one enrollment that unlocks it","pre":"Many veterans who were turned away years ago now qualify.","head":"Step zero: getting enrolled in VA health care","blocks":[{"t":"p","text":"Help at home through the VA starts with one thing: the veteran has to be enrolled in VA health care. Not just \"a veteran.\" Enrolled. A surprising number of veterans never signed up, or were told years ago they did not qualify."},{"t":"p","text":"<strong>Who can enroll.</strong> In general, a veteran who served on active duty and did not receive a dishonorable discharge. Veterans who enlisted after September 7, 1980 usually need 24 continuous months of service or the full period they were called up for, with exceptions for a service-caused disability, a hardship discharge or an \"early out.\""},{"t":"p","text":"<strong>What changed.</strong> Since March 2024 the VA has opened enrollment to veterans who were exposed to toxins or other hazards in service. That includes veterans of Vietnam, the Gulf War, Iraq, Afghanistan and other combat zones after 9/11, and veterans exposed in training or on duty at home. They can enroll directly, without first filing a disability claim. If a veteran was told \"no\" before 2024, it is worth asking again."},{"t":"p","text":"<strong>How to apply.</strong>"},{"t":"ol","items":["Find the discharge papers (DD-214). If they are lost, email 11 in this series shows how to replace them.","Apply online at va.gov (the form is called 10-10EZ), by phone at 877-222-8387, or in person at a VA clinic.","Ask for a first appointment with a VA primary care team. That team is who orders help at home."]},{"t":"p","text":"A veteran does not have to give up Medicare or their own doctor to enroll."},{"t":"p","text":"<span style=\"font-size:14px;color:#5b6b7a;\">VA rules change, and your VA care team has the final word on what you qualify for.</span>"}],"cta":{"label":"See how VA home care works","href":"https://mo-care.com/veterans","kind":"link"},"sign":"From our Springfield office,","seg":"VA leads","series":2,"footer":"You're receiving this because we share VA home care information with veterans and their families in Missouri. We send one email a month.","aud":"va","key":"v2"},{"id":3,"photo":"hero-caregiver","month":"VA leads","when":"VA series · 3","cat":"VA series","ac":"#14606F","eye":"VA benefits and care at home · 3 of 12","hero":"","subj":"Who qualifies for a VA-paid caregiver at home","pre":"It is not about income, and it is not about age.","head":"Homemaker and Home Health Aide care: who qualifies","blocks":[{"t":"p","text":"This is the VA benefit we work with every day, so here is the straight answer on who gets it."},{"t":"p","text":"<strong>The VA's own rule has three parts.</strong> An enrolled veteran is eligible for Homemaker and Home Health Aide care if:"},{"t":"ol","items":["<strong>There is a clinical need.</strong> The veteran needs help with daily activities such as bathing, dressing, eating, using the bathroom, or moving around safely. Memory loss and confusion count too.","<strong>The veteran qualifies for community care.</strong> Because the VA does not send its own aides into homes, it buys this care from agencies in the community.","<strong>The service is available where the veteran lives.</strong>"]},{"t":"p","text":"<strong>What it is not based on.</strong>"},{"t":"l","items":["Not income or savings.","Not age. A younger veteran with a need can qualify.","Not a combat record or a disability rating. A rating can affect whether the VA charges a copay, but it does not decide whether the veteran can have the care."]},{"t":"p","text":"<strong>What the caregiver does.</strong> Help with bathing, dressing, grooming, meals, medication reminders, laundry, light housekeeping, and company. It is not nursing care."},{"t":"p","text":"<strong>How much.</strong> The VA decides the number of hours from its own assessment, and reviews it over time. Nobody outside the VA can promise a number."},{"t":"p","text":"<strong>What it costs.</strong> The VA pays the agency directly. You do not pay Caring Companions for VA-authorized care. The VA may charge some veterans its own copay, depending on their service-connected disability status. The VA care team can tell you whether that applies."},{"t":"p","text":"Next month: exactly how to ask for it."},{"t":"p","text":"<span style=\"font-size:14px;color:#5b6b7a;\">VA rules change, and your VA care team has the final word on what you qualify for.</span>"}],"cta":{"label":"See how VA home care works","href":"https://mo-care.com/veterans","kind":"link"},"sign":"From our Springfield office,","seg":"VA leads","series":3,"footer":"You're receiving this because we share VA home care information with veterans and their families in Missouri. We send one email a month.","aud":"va","key":"v3"},{"id":4,"photo":"scene-evening-call","month":"VA leads","when":"VA series · 4","cat":"VA series","ac":"#14606F","eye":"VA benefits and care at home · 4 of 12","hero":"","subj":"How to ask the VA for a caregiver: the exact steps","pre":"What to say, who to say it to, and what happens next.","head":"How to ask for it, step by step","blocks":[{"t":"p","text":"Most veterans who qualify for help at home never get it, for one reason: nobody asked. Here is how to ask."},{"t":"p","text":"<strong>Step 1. Write down the hard parts.</strong> Before the appointment, list what has gotten difficult. Getting in and out of the shower. Missed pills. Not cooking. Falls or near falls. Be specific and be honest. Veterans tend to say \"I am fine,\" and the VA can only act on what it hears."},{"t":"p","text":"<strong>Step 2. Ask the right person.</strong> At the next VA primary care visit, or by calling the clinic, say:"},{"t":"p","text":"\"I am having a harder time at home. I would like to be assessed for Homemaker and Home Health Aide care.\""},{"t":"p","text":"You can also ask to speak with the VA social worker on the care team. They arrange this every day."},{"t":"p","text":"<strong>Step 3. Name the agency you want.</strong> Say: \"I would like Caring Companions to provide the care.\" We are in network with the VA Community Care Network."},{"t":"p","text":"<strong>Step 4. The assessment.</strong> The VA team looks at what the veteran can and cannot do safely. A family member can and should be part of this conversation."},{"t":"p","text":"<strong>Step 5. The authorization.</strong> If the VA approves, it sends us an authorization with the hours. We call you, meet the veteran, and start care."},{"t":"p","text":"<strong>Where families get stuck.</strong>"},{"t":"l","items":["The veteran downplays it. Go along if you can, or send the list.","The request gets lost. If you hear nothing in two weeks, call the clinic and ask for the social worker.","The forms feel like too much. Call our office. We will go through the form with you over the phone, then fax it or send it in for you, or mail it to you to look over first."]},{"t":"p","text":"<span style=\"font-size:14px;color:#5b6b7a;\">VA rules change, and your VA care team has the final word on what you qualify for.</span>"}],"cta":{"label":"See how VA home care works","href":"https://mo-care.com/veterans","kind":"link"},"sign":"From our Springfield office,","seg":"VA leads","series":4,"footer":"You're receiving this because we share VA home care information with veterans and their families in Missouri. We send one email a month.","aud":"va","key":"v4"},{"id":5,"photo":"scene-kitchen-coffee","month":"VA leads","when":"VA series · 5","cat":"VA series","ac":"#14606F","eye":"VA benefits and care at home · 5 of 12","hero":"","subj":"VA benefits have changed. Four things worth a second look","pre":"If you were told \"no\" a few years ago, read this.","head":"What has changed since you last checked","blocks":[{"t":"p","text":"A lot of veterans looked into VA benefits once, hit a wall, and never went back. Several walls have moved."},{"t":"p","text":"<strong>1. More veterans can enroll in VA health care (2024).</strong> Since March 5, 2024, veterans exposed to toxins or other hazards in service can enroll directly in VA health care. That covers most veterans of Vietnam, the Gulf War, Iraq and Afghanistan, and many who never deployed. Enrollment is the door to care at home."},{"t":"p","text":"<strong>2. The VA can now spend more on care at home (2025).</strong> A law signed in January 2025, the Elizabeth Dole Act, raised the limit on what the VA may spend to care for a veteran at home, from 65 percent of the cost of a nursing home to 100 percent. For veterans who need a lot of help, that can mean more care at home instead of a move to a facility."},{"t":"p","text":"<strong>3. The family caregiver program covers every era (2022).</strong> The VA program that pays a stipend to family caregivers used to be limited to certain service dates. Since October 2022 it is open to eligible veterans of all eras. Families already in the program from before October 2020 have their benefits protected through September 30, 2028."},{"t":"p","text":"<strong>4. The pension asset limit rises every year.</strong> The net worth limit for VA pension and Aid and Attendance goes up each December 1. A veteran or surviving spouse who was a little over the limit a few years ago may be under it now."},{"t":"p","text":"If any of these fit your family, the next step is the same: ask the VA again. And if you would like help knowing what to ask, call us."},{"t":"p","text":"<span style=\"font-size:14px;color:#5b6b7a;\">VA rules change, and your VA care team has the final word on what you qualify for.</span>"}],"cta":{"label":"See how VA home care works","href":"https://mo-care.com/veterans","kind":"link"},"sign":"From our Springfield office,","seg":"VA leads","series":5,"footer":"You're receiving this because we share VA home care information with veterans and their families in Missouri. We send one email a month.","aud":"va","key":"v5"},{"id":6,"photo":"scene-album-dad","month":"VA leads","when":"VA series · 6","cat":"VA series","ac":"#14606F","eye":"VA benefits and care at home · 6 of 12","hero":"","subj":"Getting paid to care for a veteran you love: two different paths","pre":"One runs through the VA. One runs through us.","head":"When the caregiver is family","blocks":[{"t":"p","text":"Many veterans say the same thing: \"I do not want a stranger in my house.\" And many family members are already doing the work, unpaid. There are two separate ways that can change."},{"t":"p","text":"<strong>Path 1: Become the caregiver through Caring Companions.</strong>"},{"t":"p","text":"When the VA authorizes Homemaker and Home Health Aide care and the veteran chooses us, a family member or a friend of the veteran can apply to be the caregiver."},{"t":"l","items":["You must be 18 or older.","You pass background checks and complete our orientation.","No paid caregiving experience is needed to care for your own veteran.","If hired, you are a Caring Companions employee and you are paid weekly for the authorized hours."]},{"t":"p","text":"This path depends on the veteran's need for help, not on a disability rating."},{"t":"p","text":"<strong>Path 2: The VA's own family caregiver program.</strong>"},{"t":"p","text":"The VA runs the Program of Comprehensive Assistance for Family Caregivers. For veterans who qualify, the VA pays a monthly stipend directly to one family caregiver, along with training and other support."},{"t":"l","items":["It is for veterans with a serious service-connected condition. The VA looks for a combined disability rating of 70 percent or higher and a need for in-person personal care for at least six months.","You apply to the VA with form 10-10CG, or call the VA Caregiver Support Line at 855-260-3274."]},{"t":"p","text":"If the veteran does not meet that bar, the VA still offers every caregiver training and support through its general caregiver program. It does not pay, but it helps."},{"t":"p","text":"<strong>Which one?</strong> Path 2 fits a smaller group of veterans with serious service-connected conditions. Path 1 is open to far more families. Call our office and we will help you sort out which fits."},{"t":"p","text":"<span style=\"font-size:14px;color:#5b6b7a;\">VA rules change, and your VA care team has the final word on what you qualify for.</span>"}],"cta":{"label":"See how VA home care works","href":"https://mo-care.com/veterans","kind":"link"},"sign":"From our Springfield office,","seg":"VA leads","series":6,"footer":"You're receiving this because we share VA home care information with veterans and their families in Missouri. We send one email a month.","aud":"va","key":"v6"},{"id":7,"photo":"scene-sofa-album","month":"VA leads","when":"VA series · 7","cat":"VA series","ac":"#14606F","eye":"VA benefits and care at home · 7 of 12","hero":"","subj":"Aid and Attendance: who really qualifies, and how to apply","pre":"Monthly money for wartime veterans and surviving spouses.","head":"Aid and Attendance, explained","blocks":[{"t":"p","text":"Aid and Attendance is the VA benefit people have heard of and few understand. Here is how it works."},{"t":"p","text":"<strong>What it is.</strong> Extra monthly money added to a VA pension, paid to the veteran or surviving spouse. They can use it for care at home, in assisted living, or in a nursing home. It is separate from the caregiver the VA authorizes through its health system."},{"t":"p","text":"<strong>Who qualifies.</strong> Three tests, all of which must be met."},{"t":"ol","items":["<strong>Service.</strong> The veteran served during a wartime period and meets the VA pension service rules. For most older veterans that means at least 90 days of active duty with at least one day during wartime. Combat is not required.","<strong>Need.</strong> At least one of these is true: the person needs another person to help with daily activities like bathing, feeding and dressing; has to stay in bed for much of the day because of illness; is in a nursing home because of lost mental or physical abilities; or has very limited eyesight.","<strong>Money.</strong> Income and assets are under the VA's limit. The home you live in and your car generally do not count. The limit changes every December 1, and the VA looks back three years for assets that were given away."]},{"t":"p","text":"<strong>Surviving spouses.</strong> A surviving spouse of a wartime veteran can qualify through the Survivors Pension, with the same need and money tests."},{"t":"p","text":"<strong>How to apply.</strong> The doctor completes VA Form 21-2680. It is filed with the pension application at va.gov or by mail."},{"t":"p","text":"<strong>Please do not pay anyone to file.</strong> No one may charge a fee to prepare a first VA claim. An accredited Veterans Service Officer will help at no charge. The Missouri Veterans Commission has officers who do exactly this."},{"t":"p","text":"<span style=\"font-size:14px;color:#5b6b7a;\">VA rules change, and your VA care team has the final word on what you qualify for.</span>"}],"cta":{"label":"See how VA home care works","href":"https://mo-care.com/veterans","kind":"link"},"sign":"From our Springfield office,","seg":"VA leads","series":7,"footer":"You're receiving this because we share VA home care information with veterans and their families in Missouri. We send one email a month.","aud":"va","key":"v7"},{"id":8,"photo":"scene-tired","month":"VA leads","when":"VA series · 8","cat":"VA series","ac":"#14606F","eye":"VA benefits and care at home · 8 of 12","hero":"","subj":"\"The VA told me I don't qualify.\" What to try next","pre":"A no is often about timing, not about you.","head":"If the VA said no","blocks":[{"t":"p","text":"We hear it every week: \"We tried the VA. They said no.\" Sometimes that answer is final. Often it is not. Here is what to check."},{"t":"p","text":"<strong>Was the veteran enrolled in VA health care?</strong> Help at home is ordered by a VA care team. A veteran who is not enrolled cannot get it, and enrollment rules widened in 2024."},{"t":"p","text":"<strong>Was the request for the right thing?</strong> \"Can I get help at home?\" can get a vague answer. \"I would like to be assessed for Homemaker and Home Health Aide care\" is a specific request the team has to act on."},{"t":"p","text":"<strong>Has the need changed?</strong> An assessment is a picture of one day. A fall, a hospital stay, a new diagnosis, or a spouse who can no longer manage are all reasons to ask for a new one. Needs that did not qualify two years ago may qualify now."},{"t":"p","text":"<strong>Did the veteran undersell it?</strong> Many do. Bring a written list of what is hard, and have a family member in the room or on the phone."},{"t":"p","text":"<strong>Was it the wrong benefit?</strong> A veteran turned down for Aid and Attendance because of income may still qualify for a caregiver through VA health care, which does not look at income."},{"t":"p","text":"<strong>Who to ask.</strong>"},{"t":"l","items":["The social worker on the veteran's VA care team.","The Patient Advocate at the VA medical center, if you are not getting answers.","A Veterans Service Officer, who helps at no charge."]},{"t":"p","text":"And if you are not sure what was asked for the first time, call us. We will help you work out what to ask next."},{"t":"p","text":"<span style=\"font-size:14px;color:#5b6b7a;\">VA rules change, and your VA care team has the final word on what you qualify for.</span>"}],"cta":{"label":"See how VA home care works","href":"https://mo-care.com/veterans","kind":"link"},"sign":"From our Springfield office,","seg":"VA leads","series":8,"footer":"You're receiving this because we share VA home care information with veterans and their families in Missouri. We send one email a month.","aud":"va","key":"v8"},{"id":9,"photo":"scene-hands","month":"VA leads","when":"VA series · 9","cat":"VA series","ac":"#14606F","eye":"VA benefits and care at home · 9 of 12","hero":"","subj":"What the VA offers the spouse of a veteran","pre":"What a spouse can and cannot get, without the runaround.","head":"For wives, husbands and surviving spouses","blocks":[{"t":"p","text":"Spouses do most of the caring and get the least information. Here is what applies to you."},{"t":"p","text":"<strong>If your veteran is living.</strong>"},{"t":"l","items":["The caregiver the VA authorizes is for the veteran. It does not cover care for a spouse.","It does help you, though. Hours of care in the home are hours you can rest, see your own doctor, or leave the house without worry.","The VA offers respite care so a family caregiver can take a break. Ask the veteran's VA social worker what is available.","Any caregiver of an enrolled veteran can use the VA's caregiver support program for training and someone to talk to. The Caregiver Support Line is 855-260-3274."]},{"t":"p","text":"<strong>If you are a surviving spouse.</strong>"},{"t":"l","items":["You may qualify for the Survivors Pension, with Aid and Attendance added if you need help with daily activities. It depends on the veteran's wartime service and your income and assets.","A Veterans Service Officer can check this with you at no charge."]},{"t":"p","text":"<strong>If you need care yourself and the VA does not cover you.</strong> That is a private pay conversation, and we are glad to have it. Many couples use VA-authorized hours for the veteran and add a few hours for the spouse."},{"t":"p","text":"<span style=\"font-size:14px;color:#5b6b7a;\">VA rules change, and your VA care team has the final word on what you qualify for.</span>"}],"cta":{"label":"See how VA home care works","href":"https://mo-care.com/veterans","kind":"link"},"sign":"From our Springfield office,","seg":"VA leads","series":9,"footer":"You're receiving this because we share VA home care information with veterans and their families in Missouri. We send one email a month.","aud":"va","key":"v9"},{"id":10,"photo":"scene-puzzle","month":"VA leads","when":"VA series · 10","cat":"VA series","ac":"#14606F","eye":"VA benefits and care at home · 10 of 12","hero":"","subj":"When a veteran has dementia: what the VA can do at home","pre":"Memory loss counts as a reason for help.","head":"Memory loss, and a break for the family","blocks":[{"t":"p","text":"Families caring for a veteran with memory loss often think VA home care is for physical problems. It is not only that."},{"t":"p","text":"<strong>Memory loss is a clinical need.</strong> A veteran who can still walk and dress but forgets the stove, misses medication, or cannot be left alone safely has a need the VA care team can assess. Say exactly that at the appointment: what happens when he is alone."},{"t":"p","text":"<strong>What to ask for.</strong>"},{"t":"l","items":["An assessment for Homemaker and Home Health Aide care, for regular help in the home.","Respite care, so the person doing the caring gets a break. The VA offers respite in the home and in other settings.","A referral to the VA's caregiver support team."]},{"t":"p","text":"<strong>What helps the assessment.</strong> Keep a simple log for two weeks: wandering, missed pills, nights awake, anything unsafe. It turns \"he is getting worse\" into something the team can act on."},{"t":"p","text":"<strong>What a caregiver does.</strong> Keeps a steady routine, helps with bathing and meals, gives medication reminders, and stays with the veteran so he is safe and you can step away."},{"t":"p","text":"You do not have to wait for a crisis to ask."},{"t":"p","text":"<span style=\"font-size:14px;color:#5b6b7a;\">VA rules change, and your VA care team has the final word on what you qualify for.</span>"}],"cta":{"label":"See how VA home care works","href":"https://mo-care.com/veterans","kind":"link"},"sign":"From our Springfield office,","seg":"VA leads","series":10,"footer":"You're receiving this because we share VA home care information with veterans and their families in Missouri. We send one email a month.","aud":"va","key":"v10"},{"id":11,"photo":"scene-references","month":"VA leads","when":"VA series · 11","cat":"VA series","ac":"#14606F","eye":"VA benefits and care at home · 11 of 12","hero":"","subj":"The VA paperwork checklist (and how to replace a lost DD-214)","pre":"Ten minutes now saves weeks later.","head":"Getting the papers together","blocks":[{"t":"p","text":"Almost every VA benefit asks for the same few papers. Gather them once and every later step is easier."},{"t":"p","text":"<strong>The checklist.</strong>"},{"t":"l","items":["<strong>DD-214</strong> (discharge papers). The single most important document.","<strong>Social Security number</strong> of the veteran, and of the spouse if applying for pension.","<strong>Marriage certificate</strong>, and the veteran's <strong>death certificate</strong> if a surviving spouse is applying.","<strong>Medicare and other insurance cards.</strong>","<strong>A list of doctors and current medications.</strong>","<strong>For pension or Aid and Attendance:</strong> recent bank statements, income (Social Security, retirement), and what is paid out of pocket for medical care and caregiving."]},{"t":"p","text":"<strong>If the DD-214 is lost.</strong> It can be replaced at no charge."},{"t":"ol","items":["Request it online from the National Archives at vetrecs.archives.gov, or by mail with Standard Form 180.","The veteran, or the next of kin of a veteran who has died, can make the request.","A Veterans Service Officer can request it for you."]},{"t":"p","text":"Many county recorder offices also keep a copy if the veteran filed one after coming home. It is worth a phone call."},{"t":"p","text":"<strong>Keep copies.</strong> Put everything in one folder and tell one other family member where it is."},{"t":"p","text":"If you would rather not do this alone, call our office. For VA home care forms, we will fill them out with you over the phone."},{"t":"p","text":"<span style=\"font-size:14px;color:#5b6b7a;\">VA rules change, and your VA care team has the final word on what you qualify for.</span>"}],"cta":{"label":"See how VA home care works","href":"https://mo-care.com/veterans","kind":"link"},"sign":"From our Springfield office,","seg":"VA leads","series":11,"footer":"You're receiving this because we share VA home care information with veterans and their families in Missouri. We send one email a month.","aud":"va","key":"v11"},{"id":12,"photo":"scene-welcome-porch","month":"VA leads","when":"VA series · 12","cat":"VA series","ac":"#14606F","eye":"VA benefits and care at home · 12 of 12","hero":"","subj":"You should never pay for help with a VA claim. Call these people","pre":"The helpers are real, local, and cost nothing.","head":"Who will help you, at no charge","blocks":[{"t":"p","text":"If this year of emails leaves you with one thing, let it be this: you do not have to figure out the VA alone, and you should not pay anyone to file a claim."},{"t":"p","text":"<strong>Who helps, at no charge.</strong>"},{"t":"l","items":["<strong>Veterans Service Officers.</strong> Trained, accredited people who file claims and chase answers. The Missouri Veterans Commission has them, and so do the VFW, the American Legion and the DAV.","<strong>The VA social worker</strong> on the veteran's care team. This is the person who arranges help at home.","<strong>The VA Caregiver Support Line,</strong> 855-260-3274, for the family member doing the caring.","<strong>The VA's main line,</strong> 800-698-2411, any hour, when you do not know who to call."]},{"t":"p","text":"<strong>Where we fit.</strong> We are the caregivers. When the VA authorizes care at home and the veteran chooses Caring Companions, we send the caregiver, or help a family member or friend become the caregiver. We also help with the home care paperwork over the phone."},{"t":"p","text":"<strong>The short version of everything.</strong>"},{"t":"ol","items":["Get the veteran enrolled in VA health care.","Ask the VA care team for a Homemaker and Home Health Aide assessment.","Tell them you would like Caring Companions.","Ask a Veterans Service Officer about pension and Aid and Attendance."]},{"t":"p","text":"Thank you for reading this year, and thank you for your service and for your family's."},{"t":"p","text":"<span style=\"font-size:14px;color:#5b6b7a;\">VA rules change, and your VA care team has the final word on what you qualify for.</span>"}],"cta":{"label":"See how VA home care works","href":"https://mo-care.com/veterans","kind":"link"},"sign":"From our Springfield office,","seg":"VA leads","series":12,"footer":"You're receiving this because we share VA home care information with veterans and their families in Missouri. We send one email a month.","aud":"va","key":"v12"}];
const CC_EMAIL_ASSETS = 'https://mo-care.com/email-assets';
const CC_EMAIL_LOGO = CC_EMAIL_ASSETS + '/cc-logo.png';
/* The look lives in email-template.js (2026-11-13), the same file the server's scheduled sender uses, so a preview here
   is what goes out. '{unsub}' is each person's own unsubscribe link, filled in by the server when it sends. */
function ccBuildEmailHTML(e, seg){
  /* seg: the partner type of the organization it is going to, when one partner is being written to (partner-emails.js) */
  return CCEmailTemplate.build(e, { unsub:'{unsub}', assets:CC_EMAIL_ASSETS, seg:seg || '' });
}
